{
  "name": "scalable-shopping-cart",
  "version": "1.0.0",
  "description": "Carrito de la compra escalable con Arquitectura Hexagonal, control de concurrencia optimista, idempotencia, persistencia multinivel (L1 + SQLite WAL) y API HTTP.",
  "type": "module",
  "engines": {
    "node": ">=22.6.0"
  },
  "scripts": {
    "start": "node --no-warnings src/server.ts",
    "dev": "node --no-warnings --watch src/server.ts",
    "test": "node --no-warnings --test tests/*.test.ts"
  }
}

export type DomainErrorCode =
  | 'VALIDATION_ERROR'
  | 'CURRENCY_MISMATCH'
  | 'CART_NOT_FOUND'
  | 'CART_NOT_ACTIVE'
  | 'CART_EXPIRED'
  | 'ITEM_NOT_FOUND'
  | 'PRODUCT_NOT_FOUND'
  | 'INSUFFICIENT_STOCK'
  | 'COUPON_INVALID'
  | 'CONCURRENCY_CONFLICT'
  | 'EMPTY_CART_CHECKOUT'
  | 'IDEMPOTENCY_CONFLICT';

export class DomainError extends Error {
  readonly code: DomainErrorCode;
  readonly statusCode: number;
  readonly details?: Record<string, unknown>;

  constructor(
    code: DomainErrorCode,
    message: string,
    statusCode = 400,
    details?: Record<string, unknown>,
  ) {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
    this.statusCode = statusCode;
    this.details = details;
  }
}

export class ValidationError extends DomainError {
  constructor(message: string, details?: Record<string, unknown>) {
    super('VALIDATION_ERROR', message, 400, details);
  }
}

export class NotFoundError extends DomainError {
  constructor(
    code: 'CART_NOT_FOUND' | 'ITEM_NOT_FOUND' | 'PRODUCT_NOT_FOUND',
    message: string,
  ) {
    super(code, message, 404);
  }
}

export class ConcurrencyConflictError extends DomainError {
  constructor(cartId: string, expectedVersion: number, actualVersion?: number) {
    super(
      'CONCURRENCY_CONFLICT',
      `Conflicto de concurrencia en el carrito ${cartId}: se esperaba la versión ${expectedVersion}.`,
      409,
      { cartId, expectedVersion, actualVersion },
    );
  }
}

export class InsufficientStockError extends DomainError {
  constructor(sku: string, requested: number, available: number) {
    super(
      'INSUFFICIENT_STOCK',
      `Stock insuficiente para el producto ${sku} (solicitado: ${requested}, disponible: ${available}).`,
      409,
      { sku, requested, available },
    );
  }
}

import { DomainError, ValidationError } from './errors.ts';

export type CurrencyCode = 'EUR' | 'USD' | 'MXN' | 'COP' | 'ARS' | 'CLP' | 'GBP';

const SUPPORTED_CURRENCIES = new Set<string>([
  'EUR',
  'USD',
  'MXN',
  'COP',
  'ARS',
  'CLP',
  'GBP',
]);

export interface MoneyJSON {
  amountMinor: number;
  currency: CurrencyCode;
  formatted: string;
}

/**
 * Value Object inmutable para importes monetarios exactos en unidades menores (céntimos/centavos).
 * Evita errores de coma flotante IEEE 754 en cálculos de precios, descuentos e impuestos.
 */
export class Money {
  readonly amountMinor: number;
  readonly currency: CurrencyCode;

  private constructor(amountMinor: number, currency: CurrencyCode) {
    if (!Number.isSafeInteger(amountMinor)) {
      throw new ValidationError(
        `El importe monetario debe ser un entero seguro en unidades menores. Recibido: ${amountMinor}`,
      );
    }
    if (!SUPPORTED_CURRENCIES.has(currency)) {
      throw new ValidationError(`Moneda no soportada: ${currency}`);
    }
    this.amountMinor = amountMinor;
    this.currency = currency;
  }

  static ofMinor(amountMinor: number, currency: CurrencyCode = 'EUR'): Money {
    return new Money(amountMinor, currency);
  }

  static zero(currency: CurrencyCode = 'EUR'): Money {
    return new Money(0, currency);
  }

  private assertSameCurrency(other: Money): void {
    if (this.currency !== other.currency) {
      throw new DomainError(
        'CURRENCY_MISMATCH',
        `No se pueden mezclar monedas distintas: ${this.currency} y ${other.currency}.`,
        400,
      );
    }
  }

  add(other: Money): Money {
    this.assertSameCurrency(other);
    return new Money(this.amountMinor + other.amountMinor, this.currency);
  }

  subtract(other: Money): Money {
    this.assertSameCurrency(other);
    return new Money(this.amountMinor - other.amountMinor, this.currency);
  }

  clampNonNegative(): Money {
    return this.amountMinor < 0 ? Money.zero(this.currency) : this;
  }

  multiply(quantity: number): Money {
    if (!Number.isInteger(quantity) || quantity < 0) {
      throw new ValidationError(`La cantidad debe ser un entero no negativo: ${quantity}`);
    }
    return new Money(this.amountMinor * quantity, this.currency);
  }

  /**
   * Calcula un porcentaje usando puntos básicos (100 bps = 1%, 10000 bps = 100%)
   * con redondeo half-up determinista.
   */
  percentageBps(basisPoints: number): Money {
    if (!Number.isInteger(basisPoints) || basisPoints < 0) {
      throw new ValidationError(`Los puntos básicos deben ser un entero >= 0: ${basisPoints}`);
    }
    const numerator = this.amountMinor * basisPoints;
    const rounded = Math.round(numerator / 10_000);
    return new Money(rounded, this.currency);
  }

  isGreaterThanOrEqual(other: Money): boolean {
    this.assertSameCurrency(other);
    return this.amountMinor >= other.amountMinor;
  }

  equals(other: Money): boolean {
    return this.currency === other.currency && this.amountMinor === other.amountMinor;
  }

  format(): string {
    const major = (this.amountMinor / 100).toFixed(2);
    return `${major} ${this.currency}`;
  }

  toJSON(): MoneyJSON {
    return {
      amountMinor: this.amountMinor,
      currency: this.currency,
      formatted: this.format(),
    };
  }
}

export type DomainEventType =
  | 'cart.created'
  | 'cart.item_upserted'
  | 'cart.item_removed'
  | 'cart.coupon_applied'
  | 'cart.coupon_removed'
  | 'cart.merged'
  | 'cart.checked_out'
  | 'cart.cleared';

export interface DomainEvent<TPayload = Record<string, unknown>> {
  readonly eventId: string;
  readonly type: DomainEventType;
  readonly aggregateId: string;
  readonly aggregateVersion: number;
  readonly occurredAt: string;
  readonly payload: TPayload;
}

import { DomainError } from './errors.ts';
import { Money, type CurrencyCode, type MoneyJSON } from './money.ts';

export type CouponKind = 'PERCENTAGE' | 'FIXED_AMOUNT';

export interface CouponDefinition {
  readonly code: string;
  readonly description: string;
  readonly kind: CouponKind;
  /** Puntos básicos si kind === 'PERCENTAGE' (ej. 1000 = 10%) */
  readonly percentageBps?: number;
  /** Importe fijo en unidades menores si kind === 'FIXED_AMOUNT' */
  readonly fixedAmountMinor?: number;
  readonly currency?: CurrencyCode;
  readonly minSubtotalMinor?: number;
  readonly maxDiscountMinor?: number;
  readonly active: boolean;
}

export interface DiscountLine {
  readonly code: string;
  readonly description: string;
  readonly amount: Money;
}

export interface PricedLineItem {
  readonly sku: string;
  readonly quantity: number;
  readonly unitPrice: Money;
}

export interface PricingBreakdown {
  readonly subtotal: Money;
  readonly discounts: ReadonlyArray<DiscountLine>;
  readonly discountTotal: Money;
  readonly taxableAmount: Money;
  readonly taxRateBps: number;
  readonly taxAmount: Money;
  readonly shippingAmount: Money;
  readonly grandTotal: Money;
  readonly totalUnits: number;
  readonly distinctSkus: number;
}

export interface PricingBreakdownJSON {
  subtotal: MoneyJSON;
  discounts: Array<{ code: string; description: string; amount: MoneyJSON }>;
  discountTotal: MoneyJSON;
  taxableAmount: MoneyJSON;
  taxRateBps: number;
  taxAmount: MoneyJSON;
  shippingAmount: MoneyJSON;
  grandTotal: MoneyJSON;
  totalUnits: number;
  distinctSkus: number;
}

export interface PricingConfig {
  /** Impuesto aplicable en puntos básicos (ej. 2100 = 21% IVA) */
  readonly taxRateBps: number;
  /** Umbral para envío gratuito en unidades menores */
  readonly freeShippingThresholdMinor: number;
  /** Coste estándar de envío en unidades menores */
  readonly standardShippingMinor: number;
  /** Descuento automático por volumen a partir de N unidades totales */
  readonly bulkDiscountMinUnits: number;
  readonly bulkDiscountBps: number;
}

export const DEFAULT_PRICING_CONFIG: PricingConfig = {
  taxRateBps: 2100, // 21% IVA
  freeShippingThresholdMinor: 5000, // Envío gratis desde 50.00
  standardShippingMinor: 499, // 4.99 envío estándar
  bulkDiscountMinUnits: 10, // 5% dto automático por compra en volumen (>= 10 uds)
  bulkDiscountBps: 500,
};

export class PricingEngine {
  private readonly config: PricingConfig;
  private readonly coupons: Map<string, CouponDefinition>;

  constructor(
    coupons: ReadonlyArray<CouponDefinition> = [],
    config: PricingConfig = DEFAULT_PRICING_CONFIG,
  ) {
    this.config = config;
    this.coupons = new Map(coupons.map((c) => [c.code.toUpperCase(), c]));
  }

  registerCoupon(coupon: CouponDefinition): void {
    this.coupons.set(coupon.code.toUpperCase(), coupon);
  }

  getCoupon(code: string): CouponDefinition | undefined {
    return this.coupons.get(code.trim().toUpperCase());
  }

  validateCouponForSubtotal(code: string, subtotal: Money): CouponDefinition {
    const normalized = code.trim().toUpperCase();
    const coupon = this.coupons.get(normalized);
    if (!coupon || !coupon.active) {
      throw new DomainError(
        'COUPON_INVALID',
        `El cupón '${normalized}' no existe o no está activo.`,
        400,
      );
    }
    if (coupon.currency && coupon.currency !== subtotal.currency) {
      throw new DomainError(
        'COUPON_INVALID',
        `El cupón '${normalized}' solo es válido para la moneda ${coupon.currency}.`,
        400,
      );
    }
    if (
      coupon.minSubtotalMinor !== undefined &&
      subtotal.amountMinor < coupon.minSubtotalMinor
    ) {
      const minMoney = Money.ofMinor(coupon.minSubtotalMinor, subtotal.currency);
      throw new DomainError(
        'COUPON_INVALID',
        `El cupón '${normalized}' requiere un subtotal mínimo de ${minMoney.format()}.`,
        400,
      );
    }
    return coupon;
  }

  calculate(
    items: ReadonlyArray<PricedLineItem>,
    currency: CurrencyCode,
    couponCode?: string | null,
  ): PricingBreakdown {
    let subtotal = Money.zero(currency);
    let totalUnits = 0;

    for (const item of items) {
      subtotal = subtotal.add(item.unitPrice.multiply(item.quantity));
      totalUnits += item.quantity;
    }

    if (items.length === 0) {
      const zero = Money.zero(currency);
      return {
        subtotal: zero,
        discounts: [],
        discountTotal: zero,
        taxableAmount: zero,
        taxRateBps: this.config.taxRateBps,
        taxAmount: zero,
        shippingAmount: zero,
        grandTotal: zero,
        totalUnits: 0,
        distinctSkus: 0,
      };
    }

    const discounts: DiscountLine[] = [];
    let remainingBase = subtotal;

    // 1. Regla automática por volumen
    if (totalUnits >= this.config.bulkDiscountMinUnits && this.config.bulkDiscountBps > 0) {
      const bulkAmount = remainingBase.percentageBps(this.config.bulkDiscountBps);
      if (bulkAmount.amountMinor > 0) {
        discounts.push({
          code: 'BULK_AUTO',
          description: `Descuento automático por volumen (${this.config.bulkDiscountMinUnits}+ uds)`,
          amount: bulkAmount,
        });
        remainingBase = remainingBase.subtract(bulkAmount).clampNonNegative();
      }
    }

    // 2. Cupón promocional (si sigue cumpliendo condiciones con el subtotal actual)
    if (couponCode) {
      const coupon = this.coupons.get(couponCode.toUpperCase());
      const meetsMin =
        coupon &&
        coupon.active &&
        (!coupon.currency || coupon.currency === currency) &&
        (coupon.minSubtotalMinor === undefined ||
          subtotal.amountMinor >= coupon.minSubtotalMinor);

      if (coupon && meetsMin) {
        let rawDiscount = Money.zero(currency);
        if (coupon.kind === 'PERCENTAGE' && coupon.percentageBps) {
          rawDiscount = remainingBase.percentageBps(coupon.percentageBps);
        } else if (coupon.kind === 'FIXED_AMOUNT' && coupon.fixedAmountMinor) {
          rawDiscount = Money.ofMinor(coupon.fixedAmountMinor, currency);
        }

        if (
          coupon.maxDiscountMinor !== undefined &&
          rawDiscount.amountMinor > coupon.maxDiscountMinor
        ) {
          rawDiscount = Money.ofMinor(coupon.maxDiscountMinor, currency);
        }

        if (rawDiscount.amountMinor > remainingBase.amountMinor) {
          rawDiscount = remainingBase;
        }

        if (rawDiscount.amountMinor > 0) {
          discounts.push({
            code: coupon.code,
            description: coupon.description,
            amount: rawDiscount,
          });
          remainingBase = remainingBase.subtract(rawDiscount).clampNonNegative();
        }
      }
    }

    const discountTotal = subtotal.subtract(remainingBase);
    const taxableAmount = remainingBase;
    const taxAmount = taxableAmount.percentageBps(this.config.taxRateBps);

    const shippingAmount =
      taxableAmount.amountMinor >= this.config.freeShippingThresholdMinor
        ? Money.zero(currency)
        : Money.ofMinor(this.config.standardShippingMinor, currency);

    const grandTotal = taxableAmount.add(taxAmount).add(shippingAmount);

    return {
      subtotal,
      discounts,
      discountTotal,
      taxableAmount,
      taxRateBps: this.config.taxRateBps,
      taxAmount,
      shippingAmount,
      grandTotal,
      totalUnits,
      distinctSkus: items.length,
    };
  }

  static toJSON(breakdown: PricingBreakdown): PricingBreakdownJSON {
    return {
      subtotal: breakdown.subtotal.toJSON(),
      discounts: breakdown.discounts.map((d) => ({
        code: d.code,
        description: d.description,
        amount: d.amount.toJSON(),
      })),
      discountTotal: breakdown.discountTotal.toJSON(),
      taxableAmount: breakdown.taxableAmount.toJSON(),
      taxRateBps: breakdown.taxRateBps,
      taxAmount: breakdown.taxAmount.toJSON(),
      shippingAmount: breakdown.shippingAmount.toJSON(),
      grandTotal: breakdown.grandTotal.toJSON(),
      totalUnits: breakdown.totalUnits,
      distinctSkus: breakdown.distinctSkus,
    };
  }
}

import { randomUUID } from 'node:crypto';
import { DomainError, NotFoundError, ValidationError } from './errors.ts';
import type { DomainEvent, DomainEventType } from './events.ts';
import { Money, type CurrencyCode, type MoneyJSON } from './money.ts';
import { PricingEngine, type PricingBreakdownJSON } from './pricing.ts';

export type CartStatus = 'ACTIVE' | 'CHECKED_OUT' | 'MERGED' | 'EXPIRED';

export const CART_LIMITS = {
  MAX_DISTINCT_ITEMS: 100,
  MAX_QUANTITY_PER_ITEM: 99,
  GUEST_TTL_MS: 7 * 24 * 60 * 60 * 1000, // 7 días para carritos anónimos
  USER_TTL_MS: 30 * 24 * 60 * 60 * 1000, // 30 días para usuarios autenticados
} as const;

export interface CartItemSnapshot {
  sku: string;
  name: string;
  unitPriceMinor: number;
  currency: CurrencyCode;
  quantity: number;
  imageUrl?: string;
  addedAt: string;
  updatedAt: string;
}

export interface CartSnapshot {
  id: string;
  userId: string | null;
  sessionId: string | null;
  status: CartStatus;
  currency: CurrencyCode;
  couponCode: string | null;
  items: CartItemSnapshot[];
  version: number;
  createdAt: string;
  updatedAt: string;
  expiresAt: string;
}

export interface CartItemView {
  sku: string;
  name: string;
  unitPrice: MoneyJSON;
  quantity: number;
  lineSubtotal: MoneyJSON;
  imageUrl?: string;
  addedAt: string;
  updatedAt: string;
}

export interface CartView {
  id: string;
  userId: string | null;
  sessionId: string | null;
  status: CartStatus;
  currency: CurrencyCode;
  couponCode: string | null;
  items: CartItemView[];
  pricing: PricingBreakdownJSON;
  version: number;
  createdAt: string;
  updatedAt: string;
  expiresAt: string;
}

export interface CreateCartParams {
  id?: string;
  userId?: string | null;
  sessionId?: string | null;
  currency?: CurrencyCode;
  now?: Date;
}

export interface AddOrUpdateItemInput {
  sku: string;
  name: string;
  unitPrice: Money;
  quantityDelta?: number;
  absoluteQuantity?: number;
  imageUrl?: string;
  now?: Date;
}

/**
 * Agregado Raíz del Dominio: Carrito de la Compra.
 * Mantiene invariantes de negocio, control de versión para concurrencia optimista
 * y registro de eventos de dominio desacoplados (patrón Outbox / Domain Events).
 */
export class Cart {
  readonly id: string;
  private _userId: string | null;
  private _sessionId: string | null;
  private _status: CartStatus;
  readonly currency: CurrencyCode;
  private _couponCode: string | null;
  private readonly _items: Map<string, CartItemSnapshot>;
  private _version: number;
  readonly createdAt: string;
  private _updatedAt: string;
  private _expiresAt: string;
  private _domainEvents: DomainEvent[] = [];

  private constructor(snapshot: CartSnapshot) {
    this.id = snapshot.id;
    this._userId = snapshot.userId;
    this._sessionId = snapshot.sessionId;
    this._status = snapshot.status;
    this.currency = snapshot.currency;
    this._couponCode = snapshot.couponCode;
    this._items = new Map(snapshot.items.map((item) => [item.sku, { ...item }]));
    this._version = snapshot.version;
    this.createdAt = snapshot.createdAt;
    this._updatedAt = snapshot.updatedAt;
    this._expiresAt = snapshot.expiresAt;
  }

  static create(params: CreateCartParams = {}): Cart {
    const now = params.now ?? new Date();
    const userId = params.userId?.trim() || null;
    const sessionId = params.sessionId?.trim() || null;

    if (!userId && !sessionId) {
      throw new ValidationError(
        'Un carrito debe pertenecer a un userId autenticado o a un sessionId de invitado.',
      );
    }

    const currency = params.currency ?? 'EUR';
    // Validación temprana de moneda a través del Value Object Money
    Money.zero(currency);

    const ttlMs = userId ? CART_LIMITS.USER_TTL_MS : CART_LIMITS.GUEST_TTL_MS;
    const nowIso = now.toISOString();
    const expiresIso = new Date(now.getTime() + ttlMs).toISOString();

    const cart = new Cart({
      id: params.id ?? `cart_${randomUUID()}`,
      userId,
      sessionId,
      status: 'ACTIVE',
      currency,
      couponCode: null,
      items: [],
      version: 1,
      createdAt: nowIso,
      updatedAt: nowIso,
      expiresAt: expiresIso,
    });

    cart.recordEvent('cart.created', nowIso, {
      userId,
      sessionId,
      currency,
    });

    return cart;
  }

  static fromSnapshot(snapshot: CartSnapshot): Cart {
    return new Cart(snapshot);
  }

  get userId(): string | null {
    return this._userId;
  }

  get sessionId(): string | null {
    return this._sessionId;
  }

  get status(): CartStatus {
    return this._status;
  }

  get couponCode(): string | null {
    return this._couponCode;
  }

  get version(): number {
    return this._version;
  }

  get updatedAt(): string {
    return this._updatedAt;
  }

  get expiresAt(): string {
    return this._expiresAt;
  }

  get items(): ReadonlyArray<CartItemSnapshot> {
    return Array.from(this._items.values());
  }

  getItem(sku: string): CartItemSnapshot | undefined {
    const item = this._items.get(sku.trim());
    return item ? { ...item } : undefined;
  }

  isExpired(now: Date = new Date()): boolean {
    return new Date(this._expiresAt).getTime() <= now.getTime();
  }

  private assertEditable(now: Date = new Date()): void {
    if (this._status !== 'ACTIVE') {
      throw new DomainError(
        'CART_NOT_ACTIVE',
        `El carrito ${this.id} no admite modificaciones en estado '${this._status}'.`,
        409,
      );
    }
    if (this.isExpired(now)) {
      this._status = 'EXPIRED';
      throw new DomainError(
        'CART_EXPIRED',
        `El carrito ${this.id} ha expirado.`,
        410,
      );
    }
  }

  private touch(now: Date): void {
    this._version += 1;
    this._updatedAt = now.toISOString();
    const ttlMs = this._userId ? CART_LIMITS.USER_TTL_MS : CART_LIMITS.GUEST_TTL_MS;
    this._expiresAt = new Date(now.getTime() + ttlMs).toISOString();
  }

  private recordEvent(
    type: DomainEventType,
    occurredAt: string,
    payload: Record<string, unknown>,
  ): void {
    this._domainEvents.push({
      eventId: `evt_${randomUUID()}`,
      type,
      aggregateId: this.id,
      aggregateVersion: this._version,
      occurredAt,
      payload,
    });
  }

  pullDomainEvents(): DomainEvent[] {
    const events = [...this._domainEvents];
    this._domainEvents = [];
    return events;
  }

  upsertItem(input: AddOrUpdateItemInput): void {
    const now = input.now ?? new Date();
    this.assertEditable(now);

    const sku = input.sku.trim();
    if (!sku) {
      throw new ValidationError('El SKU del producto es obligatorio.');
    }
    if (input.unitPrice.currency !== this.currency) {
      throw new DomainError(
        'CURRENCY_MISMATCH',
        `El precio del producto (${input.unitPrice.currency}) no coincide con la moneda del carrito (${this.currency}).`,
        400,
      );
    }

    const existing = this._items.get(sku);
    let nextQuantity: number;

    if (input.absoluteQuantity !== undefined) {
      nextQuantity = input.absoluteQuantity;
    } else if (input.quantityDelta !== undefined) {
      nextQuantity = (existing?.quantity ?? 0) + input.quantityDelta;
    } else {
      throw new ValidationError('Se debe especificar quantityDelta o absoluteQuantity.');
    }

    if (!Number.isInteger(nextQuantity)) {
      throw new ValidationError('La cantidad del artículo debe ser un número entero.');
    }

    if (nextQuantity <= 0) {
      if (existing) {
        this.removeItem(sku, now);
        return;
      }
      throw new ValidationError('La cantidad a añadir debe ser mayor que cero.');
    }

    if (nextQuantity > CART_LIMITS.MAX_QUANTITY_PER_ITEM) {
      throw new ValidationError(
        `No se pueden añadir más de ${CART_LIMITS.MAX_QUANTITY_PER_ITEM} unidades de un mismo SKU (${sku}).`,
        { sku, maxQuantity: CART_LIMITS.MAX_QUANTITY_PER_ITEM },
      );
    }

    if (!existing && this._items.size >= CART_LIMITS.MAX_DISTINCT_ITEMS) {
      throw new ValidationError(
        `El carrito ha alcanzado el límite máximo de ${CART_LIMITS.MAX_DISTINCT_ITEMS} productos distintos.`,
      );
    }

    const nowIso = now.toISOString();
    this._items.set(sku, {
      sku,
      name: input.name.trim(),
      unitPriceMinor: input.unitPrice.amountMinor,
      currency: this.currency,
      quantity: nextQuantity,
      imageUrl: input.imageUrl ?? existing?.imageUrl,
      addedAt: existing?.addedAt ?? nowIso,
      updatedAt: nowIso,
    });

    this.touch(now);
    this.recordEvent('cart.item_upserted', nowIso, {
      sku,
      quantity: nextQuantity,
      unitPriceMinor: input.unitPrice.amountMinor,
    });
  }

  removeItem(sku: string, now: Date = new Date()): void {
    this.assertEditable(now);
    const normalizedSku = sku.trim();
    if (!this._items.has(normalizedSku)) {
      throw new NotFoundError(
        'ITEM_NOT_FOUND',
        `El artículo '${normalizedSku}' no se encuentra en el carrito.`,
      );
    }
    this._items.delete(normalizedSku);
    this.touch(now);
    this.recordEvent('cart.item_removed', now.toISOString(), { sku: normalizedSku });
  }

  clear(now: Date = new Date()): void {
    this.assertEditable(now);
    if (this._items.size === 0 && !this._couponCode) {
      return;
    }
    this._items.clear();
    this._couponCode = null;
    this.touch(now);
    this.recordEvent('cart.cleared', now.toISOString(), {});
  }

  applyCoupon(code: string, pricingEngine: PricingEngine, now: Date = new Date()): void {
    this.assertEditable(now);
    const subtotal = this.computeSubtotal();
    const coupon = pricingEngine.validateCouponForSubtotal(code, subtotal);
    this._couponCode = coupon.code;
    this.touch(now);
    this.recordEvent('cart.coupon_applied', now.toISOString(), {
      couponCode: coupon.code,
    });
  }

  removeCoupon(now: Date = new Date()): void {
    this.assertEditable(now);
    if (!this._couponCode) return;
    const previous = this._couponCode;
    this._couponCode = null;
    this.touch(now);
    this.recordEvent('cart.coupon_removed', now.toISOString(), {
      couponCode: previous,
    });
  }

  assignToUser(userId: string, now: Date = new Date()): void {
    this.assertEditable(now);
    const trimmed = userId.trim();
    if (!trimmed) {
      throw new ValidationError('El userId no puede estar vacío.');
    }
    this._userId = trimmed;
    this.touch(now);
  }

  /**
   * Fusiona los artículos de un carrito de invitado dentro de este carrito de usuario.
   * Respeta límites por SKU y marca el carrito origen como MERGED.
   */
  mergeFrom(guestCart: Cart, maxStockBySku?: ReadonlyMap<string, number>, now: Date = new Date()): void {
    this.assertEditable(now);
    guestCart.assertEditable(now);

    if (guestCart.id === this.id) {
      return;
    }
    if (guestCart.currency !== this.currency) {
      throw new DomainError(
        'CURRENCY_MISMATCH',
        `No se pueden fusionar carritos con distintas monedas (${this.currency} vs ${guestCart.currency}).`,
        400,
      );
    }

    const nowIso = now.toISOString();
    for (const guestItem of guestCart.items) {
      const existing = this._items.get(guestItem.sku);
      if (!existing && this._items.size >= CART_LIMITS.MAX_DISTINCT_ITEMS) {
        break;
      }
      const combined = (existing?.quantity ?? 0) + guestItem.quantity;
      const stockCap = maxStockBySku?.get(guestItem.sku) ?? CART_LIMITS.MAX_QUANTITY_PER_ITEM;
      const cappedQuantity = Math.min(
        combined,
        CART_LIMITS.MAX_QUANTITY_PER_ITEM,
        Math.max(0, stockCap),
      );

      if (cappedQuantity > 0) {
        this._items.set(guestItem.sku, {
          sku: guestItem.sku,
          name: guestItem.name,
          unitPriceMinor: guestItem.unitPriceMinor,
          currency: this.currency,
          quantity: cappedQuantity,
          imageUrl: guestItem.imageUrl ?? existing?.imageUrl,
          addedAt: existing?.addedAt ?? guestItem.addedAt,
          updatedAt: nowIso,
        });
      }
    }

    if (!this._couponCode && guestCart.couponCode) {
      this._couponCode = guestCart.couponCode;
    }

    guestCart.markMergedInto(this.id, now);
    this.touch(now);
    this.recordEvent('cart.merged', nowIso, {
      sourceCartId: guestCart.id,
      resultingItemCount: this._items.size,
    });
  }

  private markMergedInto(targetCartId: string, now: Date): void {
    this._status = 'MERGED';
    this._version += 1;
    this._updatedAt = now.toISOString();
    this.recordEvent('cart.merged', this._updatedAt, {
      mergedIntoCartId: targetCartId,
    });
  }

  markCheckedOut(orderId: string, now: Date = new Date()): void {
    this.assertEditable(now);
    if (this._items.size === 0) {
      throw new DomainError(
        'EMPTY_CART_CHECKOUT',
        'No se puede completar el checkout de un carrito vacío.',
        400,
      );
    }
    this._status = 'CHECKED_OUT';
    this._version += 1;
    this._updatedAt = now.toISOString();
    this.recordEvent('cart.checked_out', this._updatedAt, {
      orderId,
      itemCount: this._items.size,
    });
  }

  computeSubtotal(): Money {
    let subtotal = Money.zero(this.currency);
    for (const item of this._items.values()) {
      const unit = Money.ofMinor(item.unitPriceMinor, this.currency);
      subtotal = subtotal.add(unit.multiply(item.quantity));
    }
    return subtotal;
  }

  toSnapshot(): CartSnapshot {
    return {
      id: this.id,
      userId: this._userId,
      sessionId: this._sessionId,
      status: this._status,
      currency: this.currency,
      couponCode: this._couponCode,
      items: Array.from(this._items.values()).map((i) => ({ ...i })),
      version: this._version,
      createdAt: this.createdAt,
      updatedAt: this._updatedAt,
      expiresAt: this._expiresAt,
    };
  }

  toView(pricingEngine: PricingEngine): CartView {
    const orderedItems = Array.from(this._items.values()).sort((a, b) =>
      a.addedAt.localeCompare(b.addedAt) || a.sku.localeCompare(b.sku),
    );

    const pricedItems = orderedItems.map((item) => ({
      sku: item.sku,
      quantity: item.quantity,
      unitPrice: Money.ofMinor(item.unitPriceMinor, this.currency),
    }));

    const breakdown = pricingEngine.calculate(
      pricedItems,
      this.currency,
      this._couponCode,
    );

    return {
      id: this.id,
      userId: this._userId,
      sessionId: this._sessionId,
      status: this._status,
      currency: this.currency,
      couponCode: this._couponCode,
      items: orderedItems.map((item) => {
        const unitPrice = Money.ofMinor(item.unitPriceMinor, this.currency);
        return {
          sku: item.sku,
          name: item.name,
          unitPrice: unitPrice.toJSON(),
          quantity: item.quantity,
          lineSubtotal: unitPrice.multiply(item.quantity).toJSON(),
          imageUrl: item.imageUrl,
          addedAt: item.addedAt,
          updatedAt: item.updatedAt,
        };
      }),
      pricing: PricingEngine.toJSON(breakdown),
      version: this._version,
      createdAt: this.createdAt,
      updatedAt: this._updatedAt,
      expiresAt: this._expiresAt,
    };
  }
}

import type { Cart } from '../domain/cart.ts';
import type { DomainEvent } from '../domain/events.ts';
import type { CurrencyCode } from '../domain/money.ts';

export interface CatalogProduct {
  readonly sku: string;
  readonly name: string;
  readonly description: string;
  readonly unitPriceMinor: number;
  readonly currency: CurrencyCode;
  readonly availableStock: number;
  readonly active: boolean;
  readonly imageUrl?: string;
}

export interface StockReservationLine {
  readonly sku: string;
  readonly quantity: number;
}

export interface StockReservation {
  readonly reservationId: string;
  readonly lines: ReadonlyArray<StockReservationLine>;
  readonly expiresAt: string;
}

export interface CartRepository {
  findById(cartId: string): Promise<Cart | null>;
  findActiveByUserId(userId: string): Promise<Cart | null>;
  findActiveBySessionId(sessionId: string): Promise<Cart | null>;
  /**
   * Persiste el agregado aplicando Control de Concurrencia Optimista (Compare-And-Swap).
   * - expectedVersion === 0 indica inserción de un nuevo carrito.
   * - expectedVersion > 0 exige que la versión persistida coincida exactamente.
   */
  save(cart: Cart, expectedVersion: number): Promise<void>;
  /**
   * Persiste atómicamente dos carritos (ej. fusión carrito invitado -> carrito usuario).
   */
  savePairAtomic(
    targetCart: Cart,
    targetExpectedVersion: number,
    sourceCart: Cart,
    sourceExpectedVersion: number,
  ): Promise<void>;
  purgeExpired(now?: Date): Promise<number>;
}

export interface CatalogInventoryPort {
  listProducts(): Promise<ReadonlyArray<CatalogProduct>>;
  getProduct(sku: string): Promise<CatalogProduct | null>;
  getProducts(skus: ReadonlyArray<string>): Promise<Map<string, CatalogProduct>>;
  reserveStock(
    reservationId: string,
    lines: ReadonlyArray<StockReservationLine>,
    ttlMs?: number,
  ): Promise<StockReservation>;
  commitReservation(reservationId: string): Promise<void>;
  releaseReservation(reservationId: string): Promise<void>;
}

export interface IdempotencyRecord<T = unknown> {
  readonly result: T;
  readonly replayed: boolean;
}

export interface IdempotencyPort {
  execute<T>(
    key: string,
    fingerprint: string,
    operation: () => Promise<T>,
    ttlMs?: number,
  ): Promise<IdempotencyRecord<T>>;
}

export type EventSubscriber = (event: DomainEvent) => void | Promise<void>;

export interface EventBusPort {
  publish(events: ReadonlyArray<DomainEvent>): Promise<void>;
  subscribe(eventType: DomainEvent['type'] | '*', subscriber: EventSubscriber): () => void;
}

import { randomUUID } from 'node:crypto';
import { Cart, type CartView } from '../domain/cart.ts';
import {
  ConcurrencyConflictError,
  DomainError,
  InsufficientStockError,
  NotFoundError,
} from '../domain/errors.ts';
import { Money, type CurrencyCode, type MoneyJSON } from '../domain/money.ts';
import { PricingEngine, type PricingBreakdownJSON } from '../domain/pricing.ts';
import type {
  CartRepository,
  CatalogInventoryPort,
  EventBusPort,
  IdempotencyPort,
} from './ports.ts';

export interface CreateOrGetCartCommand {
  userId?: string | null;
  sessionId?: string | null;
  currency?: CurrencyCode;
}

export interface AddCartItemCommand {
  cartId: string;
  sku: string;
  quantity: number;
  expectedVersion?: number;
}

export interface SetCartItemQuantityCommand {
  cartId: string;
  sku: string;
  quantity: number;
  expectedVersion?: number;
}

export interface RemoveCartItemCommand {
  cartId: string;
  sku: string;
  expectedVersion?: number;
}

export interface ApplyCouponCommand {
  cartId: string;
  couponCode: string;
  expectedVersion?: number;
}

export interface MergeCartsCommand {
  guestCartId: string;
  userId: string;
  currency?: CurrencyCode;
}

export interface CheckoutCartCommand {
  cartId: string;
  customerEmail?: string;
  shippingAddress?: string;
  expectedVersion?: number;
}

export interface PriceAdjustmentNotice {
  sku: string;
  previousUnitPrice: MoneyJSON;
  currentUnitPrice: MoneyJSON;
}

export interface OrderSnapshot {
  orderId: string;
  cartId: string;
  userId: string | null;
  sessionId: string | null;
  customerEmail: string | null;
  shippingAddress: string | null;
  reservationId: string;
  items: CartView['items'];
  pricing: PricingBreakdownJSON;
  priceAdjustments: PriceAdjustmentNotice[];
  createdAt: string;
}

export interface CheckoutResult {
  order: OrderSnapshot;
  cart: CartView;
}

export interface CartServiceDeps {
  cartRepository: CartRepository;
  catalogInventory: CatalogInventoryPort;
  pricingEngine: PricingEngine;
  eventBus: EventBusPort;
  idempotencyStore: IdempotencyPort;
  maxAutoRetries?: number;
}

export class CartService {
  private readonly repo: CartRepository;
  private readonly catalog: CatalogInventoryPort;
  private readonly pricing: PricingEngine;
  private readonly eventBus: EventBusPort;
  private readonly idempotency: IdempotencyPort;
  private readonly maxAutoRetries: number;

  constructor(deps: CartServiceDeps) {
    this.repo = deps.cartRepository;
    this.catalog = deps.catalogInventory;
    this.pricing = deps.pricingEngine;
    this.eventBus = deps.eventBus;
    this.idempotency = deps.idempotencyStore;
    this.maxAutoRetries = deps.maxAutoRetries ?? 3;
  }

  async runIdempotent<T>(
    idempotencyKey: string | undefined,
    fingerprint: string,
    operation: () => Promise<T>,
  ): Promise<{ result: T; replayed: boolean }> {
    if (!idempotencyKey) {
      return { result: await operation(), replayed: false };
    }
    return this.idempotency.execute(idempotencyKey, fingerprint, operation);
  }

  async createOrGetActiveCart(cmd: CreateOrGetCartCommand): Promise<CartView> {
    if (cmd.userId) {
      const existing = await this.repo.findActiveByUserId(cmd.userId);
      if (existing && !existing.isExpired()) {
        return existing.toView(this.pricing);
      }
    } else if (cmd.sessionId) {
      const existing = await this.repo.findActiveBySessionId(cmd.sessionId);
      if (existing && !existing.isExpired()) {
        return existing.toView(this.pricing);
      }
    }

    const cart = Cart.create({
      userId: cmd.userId,
      sessionId: cmd.sessionId,
      currency: cmd.currency ?? 'EUR',
    });

    await this.repo.save(cart, 0);
    await this.eventBus.publish(cart.pullDomainEvents());
    return cart.toView(this.pricing);
  }

  async getCart(cartId: string): Promise<CartView> {
    const cart = await this.loadCartOrThrow(cartId);
    return cart.toView(this.pricing);
  }

  async addItem(cmd: AddCartItemCommand): Promise<CartView> {
    const product = await this.loadActiveProductOrThrow(cmd.sku);

    return this.mutateWithOptimisticRetry(
      cmd.cartId,
      cmd.expectedVersion,
      async (cart) => {
        const currentQty = cart.getItem(product.sku)?.quantity ?? 0;
        const targetQty = currentQty + cmd.quantity;

        if (cmd.quantity <= 0 || !Number.isInteger(cmd.quantity)) {
          throw new DomainError(
            'VALIDATION_ERROR',
            'La cantidad a añadir debe ser un entero positivo.',
            400,
          );
        }

        if (targetQty > product.availableStock) {
          throw new InsufficientStockError(
            product.sku,
            targetQty,
            product.availableStock,
          );
        }

        cart.upsertItem({
          sku: product.sku,
          name: product.name,
          unitPrice: Money.ofMinor(product.unitPriceMinor, product.currency),
          quantityDelta: cmd.quantity,
          imageUrl: product.imageUrl,
        });
      },
    );
  }

  async setItemQuantity(cmd: SetCartItemQuantityCommand): Promise<CartView> {
    if (cmd.quantity === 0) {
      return this.removeItem({
        cartId: cmd.cartId,
        sku: cmd.sku,
        expectedVersion: cmd.expectedVersion,
      });
    }

    const product = await this.loadActiveProductOrThrow(cmd.sku);
    if (cmd.quantity > product.availableStock) {
      throw new InsufficientStockError(
        product.sku,
        cmd.quantity,
        product.availableStock,
      );
    }

    return this.mutateWithOptimisticRetry(
      cmd.cartId,
      cmd.expectedVersion,
      async (cart) => {
        cart.upsertItem({
          sku: product.sku,
          name: product.name,
          unitPrice: Money.ofMinor(product.unitPriceMinor, product.currency),
          absoluteQuantity: cmd.quantity,
          imageUrl: product.imageUrl,
        });
      },
    );
  }

  async removeItem(cmd: RemoveCartItemCommand): Promise<CartView> {
    return this.mutateWithOptimisticRetry(
      cmd.cartId,
      cmd.expectedVersion,
      async (cart) => {
        cart.removeItem(cmd.sku);
      },
    );
  }

  async clearCart(cartId: string, expectedVersion?: number): Promise<CartView> {
    return this.mutateWithOptimisticRetry(cartId, expectedVersion, async (cart) => {
      cart.clear();
    });
  }

  async applyCoupon(cmd: ApplyCouponCommand): Promise<CartView> {
    return this.mutateWithOptimisticRetry(
      cmd.cartId,
      cmd.expectedVersion,
      async (cart) => {
        cart.applyCoupon(cmd.couponCode, this.pricing);
      },
    );
  }

  async removeCoupon(cartId: string, expectedVersion?: number): Promise<CartView> {
    return this.mutateWithOptimisticRetry(cartId, expectedVersion, async (cart) => {
      cart.removeCoupon();
    });
  }

  /**
   * Fusiona un carrito anónimo (invitado) al iniciar sesión un usuario autenticado.
   * Si el usuario aún no tenía carrito activo, o bien promociona/reutiliza o fusiona atómicamente.
   */
  async mergeGuestCart(cmd: MergeCartsCommand): Promise<CartView> {
    const userId = cmd.userId.trim();
    if (!userId) {
      throw new DomainError('VALIDATION_ERROR', 'El userId es obligatorio para fusionar.', 400);
    }

    for (let attempt = 0; attempt <= this.maxAutoRetries; attempt++) {
      const guestCart = await this.loadCartOrThrow(cmd.guestCartId);
      const guestVersion = guestCart.version;

      let userCart = await this.repo.findActiveByUserId(userId);
      if (userCart && userCart.id === guestCart.id) {
        return userCart.toView(this.pricing);
      }

      // Si el usuario no tiene carrito propio y el carrito invitado es anónimo, podemos asignarlo directamente
      if (!userCart && !guestCart.userId) {
        guestCart.assignToUser(userId);
        try {
          await this.repo.save(guestCart, guestVersion);
          await this.eventBus.publish(guestCart.pullDomainEvents());
          return guestCart.toView(this.pricing);
        } catch (err) {
          if (err instanceof ConcurrencyConflictError && attempt < this.maxAutoRetries) {
            continue;
          }
          throw err;
        }
      }

      let userExpectedVersion = 0;
      if (!userCart) {
        userCart = Cart.create({
          userId,
          currency: cmd.currency ?? guestCart.currency,
        });
      } else {
        userExpectedVersion = userCart.version;
      }

      const skus = guestCart.items.map((i) => i.sku);
      const productsMap = await this.catalog.getProducts(skus);
      const stockMap = new Map<string, number>();
      for (const [sku, prod] of productsMap.entries()) {
        stockMap.set(sku, prod.active ? prod.availableStock : 0);
      }

      userCart.mergeFrom(guestCart, stockMap);

      try {
        await this.repo.savePairAtomic(
          userCart,
          userExpectedVersion,
          guestCart,
          guestVersion,
        );
        const events = [
          ...userCart.pullDomainEvents(),
          ...guestCart.pullDomainEvents(),
        ];
        await this.eventBus.publish(events);
        return userCart.toView(this.pricing);
      } catch (err) {
        if (err instanceof ConcurrencyConflictError && attempt < this.maxAutoRetries) {
          continue;
        }
        throw err;
      }
    }

    throw new ConcurrencyConflictError(cmd.guestCartId, -1);
  }

  /**
   * Ejecuta el checkout del carrito mediante una Saga coordinada:
   * 1. Revalida precios vigentes y disponibilidad en catálogo.
   * 2. Reserva inventario de forma atómica.
   * 3. Marca el carrito como CHECKED_OUT con Control de Concurrencia Optimista.
   * 4. Confirma la reserva (o la libera en compensación si falla la persistencia).
   * 5. Publica eventos de dominio para sistemas aguas abajo (órdenes, facturación, envíos).
   */
  async checkout(cmd: CheckoutCartCommand): Promise<CheckoutResult> {
    const cart = await this.loadCartOrThrow(cmd.cartId);
    const initialVersion = cmd.expectedVersion ?? cart.version;

    if (cmd.expectedVersion !== undefined && cart.version !== cmd.expectedVersion) {
      throw new ConcurrencyConflictError(cart.id, cmd.expectedVersion, cart.version);
    }

    if (cart.items.length === 0) {
      throw new DomainError(
        'EMPTY_CART_CHECKOUT',
        'No se puede realizar checkout de un carrito vacío.',
        400,
      );
    }

    const skus = cart.items.map((i) => i.sku);
    const catalogMap = await this.catalog.getProducts(skus);
    const priceAdjustments: PriceAdjustmentNotice[] = [];

    for (const item of cart.items) {
      const product = catalogMap.get(item.sku);
      if (!product || !product.active) {
        throw new NotFoundError(
          'PRODUCT_NOT_FOUND',
          `El producto '${item.sku}' ya no está disponible para la venta.`,
        );
      }
      if (item.quantity > product.availableStock) {
        throw new InsufficientStockError(
          item.sku,
          item.quantity,
          product.availableStock,
        );
      }
      if (product.unitPriceMinor !== item.unitPriceMinor) {
        const previousPrice = Money.ofMinor(item.unitPriceMinor, cart.currency);
        const currentPrice = Money.ofMinor(product.unitPriceMinor, product.currency);
        priceAdjustments.push({
          sku: item.sku,
          previousUnitPrice: previousPrice.toJSON(),
          currentUnitPrice: currentPrice.toJSON(),
        });
        cart.upsertItem({
          sku: product.sku,
          name: product.name,
          unitPrice: currentPrice,
          absoluteQuantity: item.quantity,
          imageUrl: product.imageUrl,
        });
      }
    }

    const orderId = `ord_${randomUUID()}`;
    const reservationId = `res_${randomUUID()}`;
    const lines = cart.items.map((i) => ({ sku: i.sku, quantity: i.quantity }));

    await this.catalog.reserveStock(reservationId, lines);

    try {
      cart.markCheckedOut(orderId);
      await this.repo.save(cart, initialVersion);
      await this.catalog.commitReservation(reservationId);
    } catch (error) {
      // Acción compensatoria: liberamos el stock reservado si la transacción del carrito abortó
      await this.catalog.releaseReservation(reservationId);
      throw error;
    }

    await this.eventBus.publish(cart.pullDomainEvents());

    const cartView = cart.toView(this.pricing);
    const order: OrderSnapshot = {
      orderId,
      cartId: cart.id,
      userId: cart.userId,
      sessionId: cart.sessionId,
      customerEmail: cmd.customerEmail?.trim() || null,
      shippingAddress: cmd.shippingAddress?.trim() || null,
      reservationId,
      items: cartView.items,
      pricing: cartView.pricing,
      priceAdjustments,
      createdAt: cart.updatedAt,
    };

    return {
      order,
      cart: cartView,
    };
  }

  private async mutateWithOptimisticRetry(
    cartId: string,
    explicitExpectedVersion: number | undefined,
    mutator: (cart: Cart) => Promise<void>,
  ): Promise<CartView> {
    const maxAttempts = explicitExpectedVersion !== undefined ? 1 : this.maxAutoRetries + 1;

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      const cart = await this.loadCartOrThrow(cartId);
      const expectedVersion = explicitExpectedVersion ?? cart.version;

      if (cart.version !== expectedVersion) {
        throw new ConcurrencyConflictError(cart.id, expectedVersion, cart.version);
      }

      const beforeVersion = cart.version;
      await mutator(cart);

      // Si la operación fue no-op (ej. vaciar un carrito ya vacío), evitamos escrituras innecesarias
      if (cart.version === beforeVersion) {
        return cart.toView(this.pricing);
      }

      try {
        await this.repo.save(cart, expectedVersion);
        await this.eventBus.publish(cart.pullDomainEvents());
        return cart.toView(this.pricing);
      } catch (err) {
        if (err instanceof ConcurrencyConflictError && attempt < maxAttempts) {
          continue;
        }
        throw err;
      }
    }

    throw new ConcurrencyConflictError(cartId, explicitExpectedVersion ?? -1);
  }

  private async loadCartOrThrow(cartId: string): Promise<Cart> {
    const cart = await this.repo.findById(cartId);
    if (!cart) {
      throw new NotFoundError('CART_NOT_FOUND', `Carrito '${cartId}' no encontrado.`);
    }
    return cart;
  }

  private async loadActiveProductOrThrow(sku: string) {
    const product = await this.catalog.getProduct(sku.trim());
    if (!product || !product.active) {
      throw new NotFoundError(
        'PRODUCT_NOT_FOUND',
        `El producto '${sku}' no existe o no está activo en el catálogo.`,
      );
    }
    return product;
  }
}

import { Cart, type CartSnapshot } from '../../domain/cart.ts';
import { ConcurrencyConflictError } from '../../domain/errors.ts';
import type { CartRepository } from '../../application/ports.ts';

export interface InMemoryCartRepositoryOptions {
  /** Capacidad máxima de entradas en memoria (política LRU para proteger RAM en L1) */
  maxEntries?: number;
}

export class InMemoryCartRepository implements CartRepository {
  private readonly store = new Map<string, CartSnapshot>();
  private readonly activeByUser = new Map<string, string>();
  private readonly activeBySession = new Map<string, string>();
  private readonly maxEntries: number;

  constructor(options: InMemoryCartRepositoryOptions = {}) {
    this.maxEntries = options.maxEntries ?? 10_000;
  }

  async findById(cartId: string): Promise<Cart | null> {
    const snap = this.store.get(cartId);
    if (!snap) return null;
    // Refrescar orden LRU
    this.store.delete(cartId);
    this.store.set(cartId, snap);
    return Cart.fromSnapshot(structuredClone(snap));
  }

  async findActiveByUserId(userId: string): Promise<Cart | null> {
    const cartId = this.activeByUser.get(userId);
    if (!cartId) return null;
    const cart = await this.findById(cartId);
    if (!cart || cart.status !== 'ACTIVE' || cart.isExpired()) {
      this.activeByUser.delete(userId);
      return null;
    }
    return cart;
  }

  async findActiveBySessionId(sessionId: string): Promise<Cart | null> {
    const cartId = this.activeBySession.get(sessionId);
    if (!cartId) return null;
    const cart = await this.findById(cartId);
    if (!cart || cart.status !== 'ACTIVE' || cart.isExpired()) {
      this.activeBySession.delete(sessionId);
      return null;
    }
    return cart;
  }

  async save(cart: Cart, expectedVersion: number): Promise<void> {
    this.validateCompareAndSwap(cart.id, expectedVersion);
    this.writeSnapshot(cart.toSnapshot());
  }

  async savePairAtomic(
    targetCart: Cart,
    targetExpectedVersion: number,
    sourceCart: Cart,
    sourceExpectedVersion: number,
  ): Promise<void> {
    this.validateCompareAndSwap(targetCart.id, targetExpectedVersion);
    this.validateCompareAndSwap(sourceCart.id, sourceExpectedVersion);
    this.writeSnapshot(targetCart.toSnapshot());
    this.writeSnapshot(sourceCart.toSnapshot());
  }

  invalidate(cartId: string): void {
    const existing = this.store.get(cartId);
    if (existing) {
      if (existing.userId && this.activeByUser.get(existing.userId) === cartId) {
        this.activeByUser.delete(existing.userId);
      }
      if (existing.sessionId && this.activeBySession.get(existing.sessionId) === cartId) {
        this.activeBySession.delete(existing.sessionId);
      }
      this.store.delete(cartId);
    }
  }

  putCacheSnapshot(snapshot: CartSnapshot): void {
    this.writeSnapshot(snapshot);
  }

  async purgeExpired(now: Date = new Date()): Promise<number> {
    const nowMs = now.getTime();
    let purged = 0;
    for (const [id, snap] of this.store.entries()) {
      if (new Date(snap.expiresAt).getTime() <= nowMs) {
        this.invalidate(id);
        purged += 1;
      }
    }
    return purged;
  }

  private validateCompareAndSwap(cartId: string, expectedVersion: number): void {
    const existing = this.store.get(cartId);
    if (expectedVersion === 0) {
      if (existing) {
        throw new ConcurrencyConflictError(cartId, 0, existing.version);
      }
      return;
    }
    if (!existing || existing.version !== expectedVersion) {
      throw new ConcurrencyConflictError(cartId, expectedVersion, existing?.version);
    }
  }

  private writeSnapshot(rawSnapshot: CartSnapshot): void {
    const snapshot = structuredClone(rawSnapshot);
    const previous = this.store.get(snapshot.id);

    if (previous) {
      if (previous.userId && this.activeByUser.get(previous.userId) === snapshot.id) {
        this.activeByUser.delete(previous.userId);
      }
      if (previous.sessionId && this.activeBySession.get(previous.sessionId) === snapshot.id) {
        this.activeBySession.delete(previous.sessionId);
      }
      this.store.delete(snapshot.id);
    } else if (this.store.size >= this.maxEntries) {
      const oldestKey = this.store.keys().next().value;
      if (oldestKey !== undefined) {
        this.invalidate(oldestKey);
      }
    }

    this.store.set(snapshot.id, snapshot);

    if (snapshot.status === 'ACTIVE') {
      if (snapshot.userId) {
        this.activeByUser.set(snapshot.userId, snapshot.id);
      }
      if (snapshot.sessionId) {
        this.activeBySession.set(snapshot.sessionId, snapshot.id);
      }
    }
  }
}

import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import type { CartRepository } from '../../application/ports.ts';
import { Cart, type CartItemSnapshot, type CartSnapshot, type CartStatus } from '../../domain/cart.ts';
import { ConcurrencyConflictError } from '../../domain/errors.ts';
import type { CurrencyCode } from '../../domain/money.ts';

interface CartRow {
  id: string;
  user_id: string | null;
  session_id: string | null;
  status: string;
  currency: string;
  coupon_code: string | null;
  items_json: string;
  version: number;
  created_at: string;
  updated_at: string;
  expires_at: string;
}

/**
 * Repositorio SQL transaccional (SQLite con modo WAL para lecturas concurrentes).
 * Utiliza exactamente el mismo esquema e invariantes Compare-And-Swap (WHERE id = ? AND version = ?)
 * aplicables a PostgreSQL / CockroachDB en despliegues multi-nodo.
 */
export class SqliteCartRepository implements CartRepository {
  private readonly db: DatabaseSync;

  constructor(dbPath = ':memory:') {
    if (dbPath !== ':memory:') {
      mkdirSync(dirname(dbPath), { recursive: true });
    }
    this.db = new DatabaseSync(dbPath);
    this.initializeSchema();
  }

  private initializeSchema(): void {
    this.db.exec(`
      PRAGMA journal_mode = WAL;
      PRAGMA synchronous = NORMAL;
      PRAGMA foreign_keys = ON;

      CREATE TABLE IF NOT EXISTS carts (
        id TEXT PRIMARY KEY,
        user_id TEXT,
        session_id TEXT,
        status TEXT NOT NULL,
        currency TEXT NOT NULL,
        coupon_code TEXT,
        items_json TEXT NOT NULL,
        version INTEGER NOT NULL,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL,
        expires_at TEXT NOT NULL
      );

      CREATE INDEX IF NOT EXISTS idx_carts_active_user
        ON carts (user_id, status, updated_at DESC)
        WHERE user_id IS NOT NULL AND status = 'ACTIVE';

      CREATE INDEX IF NOT EXISTS idx_carts_active_session
        ON carts (session_id, status, updated_at DESC)
        WHERE session_id IS NOT NULL AND status = 'ACTIVE';

      CREATE INDEX IF NOT EXISTS idx_carts_expires_at
        ON carts (expires_at);
    `);
  }

  async findById(cartId: string): Promise<Cart | null> {
    const stmt = this.db.prepare('SELECT * FROM carts WHERE id = ? LIMIT 1');
    const row = stmt.get(cartId) as CartRow | undefined;
    return row ? this.rowToCart(row) : null;
  }

  async findActiveByUserId(userId: string): Promise<Cart | null> {
    const nowIso = new Date().toISOString();
    const stmt = this.db.prepare(`
      SELECT * FROM carts
      WHERE user_id = ? AND status = 'ACTIVE' AND expires_at > ?
      ORDER BY updated_at DESC
      LIMIT 1
    `);
    const row = stmt.get(userId, nowIso) as CartRow | undefined;
    return row ? this.rowToCart(row) : null;
  }

  async findActiveBySessionId(sessionId: string): Promise<Cart | null> {
    const nowIso = new Date().toISOString();
    const stmt = this.db.prepare(`
      SELECT * FROM carts
      WHERE session_id = ? AND status = 'ACTIVE' AND expires_at > ?
      ORDER BY updated_at DESC
      LIMIT 1
    `);
    const row = stmt.get(sessionId, nowIso) as CartRow | undefined;
    return row ? this.rowToCart(row) : null;
  }

  async save(cart: Cart, expectedVersion: number): Promise<void> {
    this.saveSingleSync(cart.toSnapshot(), expectedVersion);
  }

  async savePairAtomic(
    targetCart: Cart,
    targetExpectedVersion: number,
    sourceCart: Cart,
    sourceExpectedVersion: number,
  ): Promise<void> {
    this.db.exec('BEGIN IMMEDIATE TRANSACTION');
    try {
      this.saveSingleSync(targetCart.toSnapshot(), targetExpectedVersion);
      this.saveSingleSync(sourceCart.toSnapshot(), sourceExpectedVersion);
      this.db.exec('COMMIT');
    } catch (error) {
      this.db.exec('ROLLBACK');
      throw error;
    }
  }

  async purgeExpired(now: Date = new Date()): Promise<number> {
    const stmt = this.db.prepare(`
      DELETE FROM carts
      WHERE expires_at <= ? AND status IN ('ACTIVE', 'EXPIRED')
    `);
    const result = stmt.run(now.toISOString());
    return Number(result.changes);
  }

  close(): void {
    this.db.close();
  }

  private saveSingleSync(snap: CartSnapshot, expectedVersion: number): void {
    const itemsJson = JSON.stringify(snap.items);

    if (expectedVersion === 0) {
      try {
        const insertStmt = this.db.prepare(`
          INSERT INTO carts (
            id, user_id, session_id, status, currency, coupon_code,
            items_json, version, created_at, updated_at, expires_at
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `);
        insertStmt.run(
          snap.id,
          snap.userId,
          snap.sessionId,
          snap.status,
          snap.currency,
          snap.couponCode,
          itemsJson,
          snap.version,
          snap.createdAt,
          snap.updatedAt,
          snap.expiresAt,
        );
        return;
      } catch (err) {
        const currentVersion = this.fetchCurrentVersion(snap.id);
        if (currentVersion !== undefined) {
          throw new ConcurrencyConflictError(snap.id, 0, currentVersion);
        }
        throw err;
      }
    }

    const updateStmt = this.db.prepare(`
      UPDATE carts
      SET user_id = ?,
          session_id = ?,
          status = ?,
          currency = ?,
          coupon_code = ?,
          items_json = ?,
          version = ?,
          updated_at = ?,
          expires_at = ?
      WHERE id = ? AND version = ?
    `);

    const result = updateStmt.run(
      snap.userId,
      snap.sessionId,
      snap.status,
      snap.currency,
      snap.couponCode,
      itemsJson,
      snap.version,
      snap.updatedAt,
      snap.expiresAt,
      snap.id,
      expectedVersion,
    );

    if (Number(result.changes) !== 1) {
      const currentVersion = this.fetchCurrentVersion(snap.id);
      throw new ConcurrencyConflictError(snap.id, expectedVersion, currentVersion);
    }
  }

  private fetchCurrentVersion(cartId: string): number | undefined {
    const stmt = this.db.prepare('SELECT version FROM carts WHERE id = ? LIMIT 1');
    const row = stmt.get(cartId) as { version: number } | undefined;
    return row?.version;
  }

  private rowToCart(row: CartRow): Cart {
    const snapshot: CartSnapshot = {
      id: row.id,
      userId: row.user_id,
      sessionId: row.session_id,
      status: row.status as CartStatus,
      currency: row.currency as CurrencyCode,
      couponCode: row.coupon_code,
      items: JSON.parse(row.items_json) as CartItemSnapshot[],
      version: row.version,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
      expiresAt: row.expires_at,
    };
    return Cart.fromSnapshot(snapshot);
  }
}

import type { CartRepository } from '../../application/ports.ts';
import type { Cart } from '../../domain/cart.ts';
import { ConcurrencyConflictError } from '../../domain/errors.ts';
import type { InMemoryCartRepository } from './in-memory-cart-repository.ts';

/**
 * Repositorio Multinivel (Read-Through + Write-Through Cache):
 * Combina una capa rápida en memoria L1 (equivalente a Redis en despliegues distribuidos)
 * con un almacén duradero transaccional L2 (SQLite / PostgreSQL).
 * La fuente de verdad para Control de Concurrencia Optimista es siempre L2.
 */
export class TieredCartRepository implements CartRepository {
  private readonly l1Cache: InMemoryCartRepository;
  private readonly l2Store: CartRepository;

  constructor(l1Cache: InMemoryCartRepository, l2Store: CartRepository) {
    this.l1Cache = l1Cache;
    this.l2Store = l2Store;
  }

  async findById(cartId: string): Promise<Cart | null> {
    const cached = await this.l1Cache.findById(cartId);
    if (cached) {
      return cached;
    }
    const persisted = await this.l2Store.findById(cartId);
    if (persisted) {
      this.l1Cache.putCacheSnapshot(persisted.toSnapshot());
    }
    return persisted;
  }

  async findActiveByUserId(userId: string): Promise<Cart | null> {
    const cached = await this.l1Cache.findActiveByUserId(userId);
    if (cached) {
      return cached;
    }
    const persisted = await this.l2Store.findActiveByUserId(userId);
    if (persisted) {
      this.l1Cache.putCacheSnapshot(persisted.toSnapshot());
    }
    return persisted;
  }

  async findActiveBySessionId(sessionId: string): Promise<Cart | null> {
    const cached = await this.l1Cache.findActiveBySessionId(sessionId);
    if (cached) {
      return cached;
    }
    const persisted = await this.l2Store.findActiveBySessionId(sessionId);
    if (persisted) {
      this.l1Cache.putCacheSnapshot(persisted.toSnapshot());
    }
    return persisted;
  }

  async save(cart: Cart, expectedVersion: number): Promise<void> {
    try {
      await this.l2Store.save(cart, expectedVersion);
      this.l1Cache.putCacheSnapshot(cart.toSnapshot());
    } catch (error) {
      if (error instanceof ConcurrencyConflictError) {
        // Invalidar L1 para asegurar que la siguiente lectura obtenga la versión fresca desde L2
        this.l1Cache.invalidate(cart.id);
      }
      throw error;
    }
  }

  async savePairAtomic(
    targetCart: Cart,
    targetExpectedVersion: number,
    sourceCart: Cart,
    sourceExpectedVersion: number,
  ): Promise<void> {
    try {
      await this.l2Store.savePairAtomic(
        targetCart,
        targetExpectedVersion,
        sourceCart,
        sourceExpectedVersion,
      );
      this.l1Cache.putCacheSnapshot(targetCart.toSnapshot());
      this.l1Cache.putCacheSnapshot(sourceCart.toSnapshot());
    } catch (error) {
      if (error instanceof ConcurrencyConflictError) {
        this.l1Cache.invalidate(targetCart.id);
        this.l1Cache.invalidate(sourceCart.id);
      }
      throw error;
    }
  }

  async purgeExpired(now: Date = new Date()): Promise<number> {
    await this.l1Cache.purgeExpired(now);
    return this.l2Store.purgeExpired(now);
  }
}

