export class InMemoryCatalogInventory implements CatalogInventoryPort {
  private readonly products = new Map<string, MutableProduct>();
  private readonly reservations = new Map<string, InternalReservation>();

  constructor(seed: ReadonlyArray<CatalogProduct> = DEFAULT_CATALOG_PRODUCTS) {
    for (const item of seed) {
      this.products.set(item.sku, {
        sku: item.sku,
        name: item.name,
        description: item.description,
        unitPriceMinor: item.unitPriceMinor,
        currency: item.currency,
        physicalStock: item.availableStock,
        reservedStock: 0,
        active: item.active,
        imageUrl: item.imageUrl,
      });
    }
  }

  async listProducts(): Promise<ReadonlyArray<CatalogProduct>> {
    this.releaseExpiredReservations();
    return Array.from(this.products.values())
      .filter((p) => p.active)
      .map((p) => this.toPublicProduct(p));
  }

  async getProduct(sku: string): Promise<CatalogProduct | null> {
    this.releaseExpiredReservations();
    const p = this.products.get(sku);
    return p ? this.toPublicProduct(p) : null;
  }

  async getProducts(skus: ReadonlyArray<string>): Promise<Map<string, CatalogProduct>> {
    this.releaseExpiredReservations();
    const result = new Map<string, CatalogProduct>();
    for (const sku of skus) {
      const p = this.products.get(sku);
      if (p) {
        result.set(sku, this.toPublicProduct(p));
      }
    }
    return result;
  }

  upsertProduct(product: CatalogProduct): void {
    const existing = this.products.get(product.sku);
    this.products.set(product.sku, {
      sku: product.sku,
      name: product.name,
      description: product.description,
      unitPriceMinor: product.unitPriceMinor,
      currency: product.currency,
      physicalStock: product.availableStock + (existing?.reservedStock ?? 0),
      reservedStock: existing?.reservedStock ?? 0,
      active: product.active,
      imageUrl: product.imageUrl,
    });
  }

  async reserveStock(
    reservationId: string,
    lines: ReadonlyArray<StockReservationLine>,
    ttlMs = 15 * 60 * 1000,
  ): Promise<StockReservation> {
    this.releaseExpiredReservations();

    const existing = this.reservations.get(reservationId);
    if (existing && existing.status === 'PENDING') {
      return {
        reservationId: existing.reservationId,
        lines: existing.lines,
        expiresAt: new Date(existing.expiresAtMs).toISOString(),
      };
    }

    // Fase 1: Validar disponibilidad completa antes de mutar (atomicidad todo-o-nada)
    for (const line of lines) {
      const product = this.products.get(line.sku);
      if (!product || !product.active) {
        throw new NotFoundError(
          'PRODUCT_NOT_FOUND',
          `Producto '${line.sku}' no disponible para reserva.`,
        );
      }
      const available = product.physicalStock - product.reservedStock;
      if (line.quantity > available) {
        throw new InsufficientStockError(line.sku, line.quantity, available);
      }
    }

    // Fase 2: Aplicar reserva
    for (const line of lines) {
      const product = this.products.get(line.sku)!;
      product.reservedStock += line.quantity;
    }

    const expiresAtMs = Date.now() + ttlMs;
    this.reservations.set(reservationId, {
      reservationId,
      lines: lines.map((l) => ({ ...l })),
      expiresAtMs,
      status: 'PENDING',
    });

    return {
      reservationId,
      lines,
      expiresAt: new Date(expiresAtMs).toISOString(),
    };
  }

  async commitReservation(reservationId: string): Promise<void> {
    const res = this.reservations.get(reservationId);
    if (!res || res.status !== 'PENDING') return;

    for (const line of res.lines) {
      const product = this.products.get(line.sku);
      if (product) {
        product.reservedStock = Math.max(0, product.reservedStock - line.quantity);
        product.physicalStock = Math.max(0, product.physicalStock - line.quantity);
      }
    }
    res.status = 'COMMITTED';
  }

  async releaseReservation(reservationId: string): Promise<void> {
    const res = this.reservations.get(reservationId);
    if (!res || res.status !== 'PENDING') return;

    for (const line of res.lines) {
      const product = this.products.get(line.sku);
      if (product) {
        product.reservedStock = Math.max(0, product.reservedStock - line.quantity);
      }
    }
    res.status = 'RELEASED';
  }

  releaseExpiredReservations(nowMs = Date.now()): void {
    for (const res of this.reservations.values()) {
      if (res.status === 'PENDING' && res.expiresAtMs <= nowMs) {
        for (const line of res.lines) {
          const product = this.products.get(line.sku);
          if (product) {
            product.reservedStock = Math.max(0, product.reservedStock - line.quantity);
          }
        }
        res.status = 'RELEASED';
      }
    }
  }

  private toPublicProduct(p: MutableProduct): CatalogProduct {
    return {
      sku: p.sku,
      name: p.name,
      description: p.description,
      unitPriceMinor: p.unitPriceMinor,
      currency: p.currency,
      availableStock: Math.max(0, p.physicalStock - p.reservedStock),
      active: p.active,
      imageUrl: p.imageUrl,
    };
  }
}

import type { IdempotencyPort, IdempotencyRecord } from '../../application/ports.ts';
import { DomainError } from '../../domain/errors.ts';

interface StoredEntry {
  fingerprint: string;
  result: unknown;
  expiresAtMs: number;
}

interface InFlightEntry {
  fingerprint: string;
  promise: Promise<unknown>;
}

/**
 * Almacén de Idempotencia con deduplicación de peticiones en vuelo (Singleflight)
 * y verificación de huella (fingerprint) para evitar reutilizar una misma Idempotency-Key
 * con parámetros de negocio distintos.
 */
export class InMemoryIdempotencyStore implements IdempotencyPort {
  private readonly completed = new Map<string, StoredEntry>();
  private readonly inFlight = new Map<string, InFlightEntry>();
  private readonly maxEntries: number;
  private readonly defaultTtlMs: number;

  constructor(maxEntries = 10_000, defaultTtlMs = 24 * 60 * 60 * 1000) {
    this.maxEntries = maxEntries;
    this.defaultTtlMs = defaultTtlMs;
  }

  async execute<T>(
    key: string,
    fingerprint: string,
    operation: () => Promise<T>,
    ttlMs = this.defaultTtlMs,
  ): Promise<IdempotencyRecord<T>> {
    const normalizedKey = key.trim();
    const now = Date.now();

    const cached = this.completed.get(normalizedKey);
    if (cached) {
      if (cached.expiresAtMs > now) {
        if (cached.fingerprint !== fingerprint) {
          throw new DomainError(
            'IDEMPOTENCY_CONFLICT',
            `La clave de idempotencia '${normalizedKey}' ya fue utilizada con un payload distinto.`,
            409,
          );
        }
        return {
          result: structuredClone(cached.result) as T,
          replayed: true,
        };
      }
      this.completed.delete(normalizedKey);
    }

    const active = this.inFlight.get(normalizedKey);
    if (active) {
      if (active.fingerprint !== fingerprint) {
        throw new DomainError(
          'IDEMPOTENCY_CONFLICT',
          `La clave de idempotencia '${normalizedKey}' está en curso con un payload distinto.`,
          409,
        );
      }
      const sharedResult = (await active.promise) as T;
      return {
        result: structuredClone(sharedResult),
        replayed: true,
      };
    }

    const executionPromise = operation();
    this.inFlight.set(normalizedKey, { fingerprint, promise: executionPromise });

    try {
      const result = await executionPromise;
      if (this.completed.size >= this.maxEntries) {
        const oldestKey = this.completed.keys().next().value;
        if (oldestKey !== undefined) {
          this.completed.delete(oldestKey);
        }
      }
      this.completed.set(normalizedKey, {
        fingerprint,
        result: structuredClone(result),
        expiresAtMs: Date.now() + ttlMs,
      });
      return { result, replayed: false };
    } finally {
      this.inFlight.delete(normalizedKey);
    }
  }
}

import type { EventBusPort, EventSubscriber } from '../../application/ports.ts';
import type { DomainEvent } from '../../domain/events.ts';

export class InMemoryEventBus implements EventBusPort {
  private readonly subscribers = new Map<string, Set<EventSubscriber>>();
  private readonly recentEvents: DomainEvent[] = [];
  private readonly maxHistory: number;

  constructor(maxHistory = 500) {
    this.maxHistory = maxHistory;
  }

  async publish(events: ReadonlyArray<DomainEvent>): Promise<void> {
    for (const event of events) {
      if (this.recentEvents.length >= this.maxHistory) {
        this.recentEvents.shift();
      }
      this.recentEvents.push(event);

      const typedHandlers = this.subscribers.get(event.type);
      const wildcardHandlers = this.subscribers.get('*');

      if (typedHandlers) {
        for (const handler of typedHandlers) {
          await handler(event);
        }
      }
      if (wildcardHandlers) {
        for (const handler of wildcardHandlers) {
          await handler(event);
        }
      }
    }
  }

  subscribe(
    eventType: DomainEvent['type'] | '*',
    subscriber: EventSubscriber,
  ): () => void {
    let set = this.subscribers.get(eventType);
    if (!set) {
      set = new Set();
      this.subscribers.set(eventType, set);
    }
    set.add(subscriber);
    return () => {
      set.delete(subscriber);
    };
  }

  getRecentEvents(limit = 50): ReadonlyArray<DomainEvent> {
    return this.recentEvents.slice(-limit);
  }
}

import type { IncomingMessage } from 'node:http';
import { ValidationError } from '../../domain/errors.ts';

const MAX_BODY_BYTES = 64 * 1024; // Límite de 64 KB para mitigar ataques de payload gigante

export async function readJsonBody(
  req: IncomingMessage,
): Promise<Record<string, unknown>> {
  const chunks: Buffer[] = [];
  let totalBytes = 0;

  for await (const chunk of req) {
    const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
    totalBytes += buf.length;
    if (totalBytes > MAX_BODY_BYTES) {
      throw new ValidationError(
        `El tamaño del cuerpo supera el máximo permitido (${MAX_BODY_BYTES} bytes).`,
      );
    }
    chunks.push(buf);
  }

  if (totalBytes === 0) {
    return {};
  }

  const raw = Buffer.concat(chunks).toString('utf8').trim();
  if (!raw) {
    return {};
  }

  try {
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
      throw new ValidationError('El cuerpo JSON debe ser un objeto.');
    }
    return parsed as Record<string, unknown>;
  } catch (err) {
    if (err instanceof ValidationError) throw err;
    throw new ValidationError('JSON malformado en el cuerpo de la petición.');
  }
}

export function parseIfMatchVersion(
  ifMatchHeader: string | string[] | undefined,
  bodyExpectedVersion?: unknown,
): number | undefined {
  if (typeof bodyExpectedVersion === 'number') {
    if (!Number.isInteger(bodyExpectedVersion) || bodyExpectedVersion < 1) {
      throw new ValidationError('expectedVersion debe ser un entero positivo.');
    }
    return bodyExpectedVersion;
  }

  const rawHeader = Array.isArray(ifMatchHeader) ? ifMatchHeader[0] : ifMatchHeader;
  if (!rawHeader) return undefined;

  // Soporta formatos estándar ETag: W/"v3", "v3", "3", 3
  const cleaned = rawHeader
    .trim()
    .replace(/^W\//i, '')
    .replace(/^"|"$/g, '')
    .replace(/^v/i, '');

  const parsed = Number(cleaned);
  if (!Number.isInteger(parsed) || parsed < 1) {
    throw new ValidationError(`Cabecera If-Match inválida: '${rawHeader}'.`);
  }
  return parsed;
}

export function requireNonEmptyString(
  obj: Record<string, unknown>,
  field: string,
): string {
  const val = obj[field];
  if (typeof val !== 'string' || val.trim().length === 0) {
    throw new ValidationError(`El campo '${field}' es obligatorio y debe ser texto.`);
  }
  return val.trim();
}

export function optionalString(
  obj: Record<string, unknown>,
  field: string,
): string | undefined {
  const val = obj[field];
  if (val === undefined || val === null) return undefined;
  if (typeof val !== 'string') {
    throw new ValidationError(`El campo '${field}' debe ser una cadena de texto.`);
  }
  const trimmed = val.trim();
  return trimmed.length > 0 ? trimmed : undefined;
}

export function requireNonNegativeInt(
  obj: Record<string, unknown>,
  field: string,
): number {
  const val = obj[field];
  if (typeof val !== 'number' || !Number.isInteger(val) || val < 0) {
    throw new ValidationError(
      `El campo '${field}' debe ser un número entero mayor o igual a 0.`,
    );
  }
  return val;
}

