            <span class="prod-price">\${(p.unitPriceMinor / 100).toFixed(2)} \${p.currency}</span>
            <button onclick="addItem('\${p.sku}')">+ Añadir</button>
          </div>
        </div>
      \`).join('');
    }

    async function initCart() {
      const { cart } = await api('/api/v1/carts', {
        method: 'POST',
        body: JSON.stringify({ sessionId })
      });
      renderCart(cart);
    }

    function renderCart(cart) {
      currentCart = cart;
      document.getElementById('cartMeta').textContent =
        \`\${cart.id.slice(0, 13)}… | v\${cart.version} | \${cart.userId ? 'User: ' + cart.userId : 'Invitado'}\`;
      const itemsEl = document.getElementById('cartItems');
      if (!cart.items.length) {
        itemsEl.innerHTML = '<p class="muted">El carrito está vacío.</p>';
      } else {
        itemsEl.innerHTML = cart.items.map(i => \`
          <div class="cart-line">
            <div>
              <div><strong>\${i.name}</strong></div>
              <div class="muted">\${i.unitPrice.formatted} x \${i.quantity} = \${i.lineSubtotal.formatted}</div>
            </div>
            <div style="display:flex;gap:0.35rem;">
              <button class="secondary" onclick="setQty('\${i.sku}', \${i.quantity - 1})">-</button>
              <button class="secondary" onclick="setQty('\${i.sku}', \${i.quantity + 1})">+</button>
            </div>
          </div>
        \`).join('');
      }
      const p = cart.pricing;
      document.getElementById('cartTotals').innerHTML = \`
        <div><span>Subtotal (\${p.totalUnits} uds)</span><span>\${p.subtotal.formatted}</span></div>
        \${p.discounts.map(d => \`<div style="color:#38bdf8"><span>Dto \${d.code}</span><span>-\${d.amount.formatted}</span></div>\`).join('')}
        <div><span>IVA (\${(p.taxRateBps / 100).toFixed(0)}%)</span><span>\${p.taxAmount.formatted}</span></div>
        <div><span>Envío</span><span>\${p.shippingAmount.formatted}</span></div>
        <div class="grand"><span>Total</span><span>\${p.grandTotal.formatted}</span></div>
      \`;
    }

    async function addItem(sku) {
      try {
        const { cart } = await api(\`/api/v1/carts/\${currentCart.id}/items\`, {
          method: 'POST',
          body: JSON.stringify({ sku, quantity: 1 })
        });
        renderCart(cart);
        notify('Artículo añadido (v' + cart.version + ')');
      } catch (e) { notify(e.message); }
    }

    async function setQty(sku, quantity) {
      try {
        const { cart } = await api(\`/api/v1/carts/\${currentCart.id}/items/\${encodeURIComponent(sku)}\`, {
          method: 'PUT',
          body: JSON.stringify({ quantity })
        });
        renderCart(cart);
      } catch (e) { notify(e.message); }
    }

    async function applyCoupon() {
      const code = document.getElementById('couponInput').value.trim();
      if (!code) return;
      try {
        const { cart } = await api(\`/api/v1/carts/\${currentCart.id}/coupons\`, {
          method: 'POST',
          body: JSON.stringify({ code })
        });
        renderCart(cart);
        notify('Cupón ' + code.toUpperCase() + ' aplicado');
      } catch (e) { notify(e.message); }
    }

    async function removeCoupon() {
      try {
        const { cart } = await api(\`/api/v1/carts/\${currentCart.id}/coupons\`, { method: 'DELETE' });
        renderCart(cart);
        notify('Cupón eliminado');
      } catch (e) { notify(e.message); }
    }

    async function mergeToUser() {
      const userId = document.getElementById('userInput').value.trim();
      if (!userId) return notify('Introduce un userId');
      try {
        const { cart } = await api('/api/v1/carts/merge', {
          method: 'POST',
          headers: {},
          body: JSON.stringify({ guestCartId: currentCart.id, userId })
        });
        renderCart(cart);
        notify('Carrito fusionado a ' + userId);
      } catch (e) { notify(e.message); }
    }

    async function clearCart() {
      try {
        const { cart } = await api(\`/api/v1/carts/\${currentCart.id}/items\`, { method: 'DELETE' });
        renderCart(cart);
        notify('Carrito vaciado');
      } catch (e) { notify(e.message); }
    }

    async function checkoutCart() {
      try {
        const { order } = await api(\`/api/v1/carts/\${currentCart.id}/checkout\`, {
          method: 'POST',
          body: JSON.stringify({ customerEmail: 'cliente@ejemplo.es' })
        });
        notify('Orden confirmada: ' + order.orderId + ' (' + order.pricing.grandTotal.formatted + ')');
        sessionId = 'sess_' + Math.random().toString(36).slice(2, 10);
        localStorage.setItem(sessionKey, sessionId);
        await loadCatalog();
        await initCart();
      } catch (e) { notify(e.message); }
    }

    loadCatalog().then(initCart);
  </script>
</body>
</html>`;
}

import { createHash } from 'node:crypto';
import type { IncomingMessage, ServerResponse } from 'node:http';
import type { CartService } from '../../application/cart-service.ts';
import type { CatalogInventoryPort } from '../../application/ports.ts';
import type { CartView } from '../../domain/cart.ts';
import { DomainError, NotFoundError } from '../../domain/errors.ts';
import type { CurrencyCode } from '../../domain/money.ts';
import type { InMemoryEventBus } from '../../infrastructure/events/in-memory-event-bus.ts';
import { renderPlaygroundHtml } from './ui.ts';
import {
  optionalString,
  parseIfMatchVersion,
  readJsonBody,
  requireNonEmptyString,
  requireNonNegativeInt,
} from './validation.ts';

export interface HttpRouterDeps {
  cartService: CartService;
  catalogInventory: CatalogInventoryPort;
  eventBus: InMemoryEventBus;
}

export function createHttpHandler(deps: HttpRouterDeps) {
  const { cartService, catalogInventory, eventBus } = deps;

  return async function handleRequest(
    req: IncomingMessage,
    res: ServerResponse,
  ): Promise<void> {
    const startHr = process.hrtime.bigint();
    try {
      const method = req.method ?? 'GET';
      const url = new URL(req.url ?? '/', 'http://localhost');
      const pathname = url.pathname.replace(/\/+$/, '') || '/';

      // Cabeceras estándar de seguridad y CORS básico para clientes SPA/Móvil
      res.setHeader('X-Content-Type-Options', 'nosniff');
      res.setHeader('Access-Control-Allow-Origin', '*');
      res.setHeader(
        'Access-Control-Allow-Methods',
        'GET, POST, PUT, DELETE, OPTIONS',
      );
      res.setHeader(
        'Access-Control-Allow-Headers',
        'Content-Type, If-Match, Idempotency-Key',
      );
      res.setHeader('Access-Control-Expose-Headers', 'ETag, X-Idempotent-Replay');

      if (method === 'OPTIONS') {
        res.writeHead(204);
        res.end();
        return;
      }

      // 1. UI interactiva
      if (method === 'GET' && pathname === '/') {
        const html = renderPlaygroundHtml();
        res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
        res.end(html);
        return;
      }

      // 2. Healthcheck para balanceadores L7 / Kubernetes probes
      if (method === 'GET' && pathname === '/health') {
        sendJson(res, 200, {
          status: 'ok',
          uptimeSeconds: Math.round(process.uptime()),
          timestamp: new Date().toISOString(),
        });
        return;
      }

      // 3. Catálogo de productos
      if (method === 'GET' && pathname === '/api/v1/products') {
        const products = await catalogInventory.listProducts();
        sendJson(res, 200, { products });
        return;
      }

      // 4. Observabilidad de eventos recientes
      if (method === 'GET' && pathname === '/api/v1/events') {
        const limitParam = Number(url.searchParams.get('limit') ?? 50);
        const limit = Number.isFinite(limitParam) ? Math.min(200, Math.max(1, limitParam)) : 50;
        sendJson(res, 200, { events: eventBus.getRecentEvents(limit) });
        return;
      }

      // 5. Crear o recuperar carrito activo
      if (method === 'POST' && pathname === '/api/v1/carts') {
        const body = await readJsonBody(req);
        const idempotencyKey = headerValue(req, 'idempotency-key');
        const fingerprint = hashPayload('POST:/api/v1/carts', body);

        const { result: cart, replayed } = await cartService.runIdempotent(
          idempotencyKey,
          fingerprint,
          () =>
            cartService.createOrGetActiveCart({
              userId: optionalString(body, 'userId'),
              sessionId: optionalString(body, 'sessionId'),
              currency: optionalString(body, 'currency') as CurrencyCode | undefined,
            }),
        );

        sendCartResponse(res, 201, cart, replayed);
        return;
      }

      // 6. Fusionar carrito de invitado a usuario autenticado
      if (method === 'POST' && pathname === '/api/v1/carts/merge') {
        const body = await readJsonBody(req);
        const guestCartId = requireNonEmptyString(body, 'guestCartId');
        const userId = requireNonEmptyString(body, 'userId');
        const idempotencyKey = headerValue(req, 'idempotency-key');
        const fingerprint = hashPayload('POST:/api/v1/carts/merge', body);

        const { result: cart, replayed } = await cartService.runIdempotent(
          idempotencyKey,
          fingerprint,
          () =>
            cartService.mergeGuestCart({
              guestCartId,
              userId,
              currency: optionalString(body, 'currency') as CurrencyCode | undefined,
            }),
        );

        sendCartResponse(res, 200, cart, replayed);
        return;
      }

      // Rutas parametrizadas bajo /api/v1/carts/:cartId...
      const segments = pathname.split('/').filter(Boolean);
      if (segments[0] === 'api' && segments[1] === 'v1' && segments[2] === 'carts') {
        const cartId = decodeURIComponent(segments[3] ?? '');
        if (!cartId) {
          throw new NotFoundError('CART_NOT_FOUND', 'Ruta de carrito no válida.');
        }

        // GET /api/v1/carts/:cartId
        if (segments.length === 4 && method === 'GET') {
          const cart = await cartService.getCart(cartId);
          sendCartResponse(res, 200, cart, false);
          return;
        }

        // POST /api/v1/carts/:cartId/items
        if (segments.length === 5 && segments[4] === 'items' && method === 'POST') {
          const body = await readJsonBody(req);
          const sku = requireNonEmptyString(body, 'sku');
          const quantity = requireNonNegativeInt(body, 'quantity');
          const expectedVersion = parseIfMatchVersion(
            req.headers['if-match'],
            body.expectedVersion,
          );
          const idempotencyKey = headerValue(req, 'idempotency-key');
          const fingerprint = hashPayload(`POST:${pathname}`, body);

          const { result: cart, replayed } = await cartService.runIdempotent(
            idempotencyKey,
            fingerprint,
            () =>
              cartService.addItem({
                cartId,
                sku,
                quantity,
                expectedVersion,
              }),
          );

          sendCartResponse(res, 200, cart, replayed);
          return;
        }

        // DELETE /api/v1/carts/:cartId/items (Vaciar carrito)
        if (segments.length === 5 && segments[4] === 'items' && method === 'DELETE') {
          const expectedVersion = parseIfMatchVersion(req.headers['if-match']);
          const cart = await cartService.clearCart(cartId, expectedVersion);
          sendCartResponse(res, 200, cart, false);
          return;
        }

        // PUT | DELETE /api/v1/carts/:cartId/items/:sku
        if (segments.length === 6 && segments[4] === 'items') {
          const sku = decodeURIComponent(segments[5] ?? '');
          if (method === 'PUT') {
            const body = await readJsonBody(req);
            const quantity = requireNonNegativeInt(body, 'quantity');
            const expectedVersion = parseIfMatchVersion(
              req.headers['if-match'],
              body.expectedVersion,
            );
            const cart = await cartService.setItemQuantity({
              cartId,
              sku,
              quantity,
              expectedVersion,
            });
            sendCartResponse(res, 200, cart, false);
            return;
          }

          if (method === 'DELETE') {
            const expectedVersion = parseIfMatchVersion(req.headers['if-match']);
            const cart = await cartService.removeItem({
              cartId,
              sku,
              expectedVersion,
            });
            sendCartResponse(res, 200, cart, false);
            return;
          }
        }

        // POST | DELETE /api/v1/carts/:cartId/coupons
        if (segments.length === 5 && segments[4] === 'coupons') {
          if (method === 'POST') {
            const body = await readJsonBody(req);
            const couponCode = requireNonEmptyString(body, 'code');
            const expectedVersion = parseIfMatchVersion(
              req.headers['if-match'],
              body.expectedVersion,
            );
            const cart = await cartService.applyCoupon({
              cartId,
              couponCode,
              expectedVersion,
            });
            sendCartResponse(res, 200, cart, false);
            return;
          }

          if (method === 'DELETE') {
            const expectedVersion = parseIfMatchVersion(req.headers['if-match']);
            const cart = await cartService.removeCoupon(cartId, expectedVersion);
            sendCartResponse(res, 200, cart, false);
            return;
          }
        }

        // POST /api/v1/carts/:cartId/checkout
        if (segments.length === 5 && segments[4] === 'checkout' && method === 'POST') {
          const body = await readJsonBody(req);
          const expectedVersion = parseIfMatchVersion(
            req.headers['if-match'],
            body.expectedVersion,
          );
          const idempotencyKey = headerValue(req, 'idempotency-key');
          const fingerprint = hashPayload(`POST:${pathname}`, body);

          const { result, replayed } = await cartService.runIdempotent(
            idempotencyKey,
            fingerprint,
            () =>
              cartService.checkout({
                cartId,
                customerEmail: optionalString(body, 'customerEmail'),
                shippingAddress: optionalString(body, 'shippingAddress'),
                expectedVersion,
              }),
          );

          res.setHeader('ETag', `W/"v${result.cart.version}"`);
          res.setHeader('X-Idempotent-Replay', String(replayed));
          sendJson(res, 200, result);
          return;
        }
      }

      sendJson(res, 404, {
        error: {
          code: 'ROUTE_NOT_FOUND',
          message: `Ruta no encontrada: ${method} ${pathname}`,
        },
      });
    } catch (error) {
      if (error instanceof DomainError) {
        sendJson(res, error.statusCode, {
          error: {
            code: error.code,
            message: error.message,
            details: error.details,
          },
        });
        return;
      }

      console.error('[HTTP Unhandled Error]', error);
      sendJson(res, 500, {
        error: {
          code: 'INTERNAL_SERVER_ERROR',
          message: 'Error interno inesperado en el servidor.',
        },
      });
    } finally {
      const durationMs = Number(process.hrtime.bigint() - startHr) / 1_000_000;
      if (!res.headersSent) {
        res.setHeader('X-Response-Time-Ms', durationMs.toFixed(2));
      }
    }
  };
}

function sendCartResponse(
  res: ServerResponse,
  statusCode: number,
  cart: CartView,
  replayed: boolean,
): void {
  res.setHeader('ETag', `W/"v${cart.version}"`);
  res.setHeader('X-Idempotent-Replay', String(replayed));
  sendJson(res, statusCode, { cart });
}

function sendJson(res: ServerResponse, statusCode: number, payload: unknown): void {
  const json = JSON.stringify(payload);
  res.writeHead(statusCode, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(json),
  });
  res.end(json);
}

function headerValue(req: IncomingMessage, name: string): string | undefined {
  const val = req.headers[name.toLowerCase()];
  const single = Array.isArray(val) ? val[0] : val;
  return single?.trim() || undefined;
}

function hashPayload(scope: string, body: Record<string, unknown>): string {
  return createHash('sha256')
    .update(`${scope}:${JSON.stringify(body)}`)
    .digest('hex');
}

import { createServer, type Server } from 'node:http';
import { pathToFileURL } from 'node:url';
import { CartService } from './application/cart-service.ts';
import { PricingEngine } from './domain/pricing.ts';
import {
  DEFAULT_COUPONS,
  InMemoryCatalogInventory,
} from './infrastructure/catalog/in-memory-catalog-inventory.ts';
import { InMemoryEventBus } from './infrastructure/events/in-memory-event-bus.ts';
import { InMemoryIdempotencyStore } from './infrastructure/idempotency/in-memory-idempotency-store.ts';
import { InMemoryCartRepository } from './infrastructure/persistence/in-memory-cart-repository.ts';
import { SqliteCartRepository } from './infrastructure/persistence/sqlite-cart-repository.ts';
import { TieredCartRepository } from './infrastructure/persistence/tiered-cart-repository.ts';
import { createHttpHandler } from './interfaces/http/router.ts';

export interface AppConfig {
  sqlitePath?: string;
  l1MaxEntries?: number;
  purgeIntervalMs?: number;
}

export interface ShoppingCartApp {
  readonly server: Server;
  readonly cartService: CartService;
  readonly catalogInventory: InMemoryCatalogInventory;
  readonly pricingEngine: PricingEngine;
  readonly eventBus: InMemoryEventBus;
  readonly l1Cache: InMemoryCartRepository;
  readonly sqliteRepo: SqliteCartRepository;
  readonly cartRepository: TieredCartRepository;
  close(): Promise<void>;
}

export function createShoppingCartApp(config: AppConfig = {}): ShoppingCartApp {
  const sqlitePath = config.sqlitePath ?? process.env.CART_DB_PATH ?? './data/carts.sqlite';
  const l1Cache = new InMemoryCartRepository({
    maxEntries: config.l1MaxEntries ?? 5_000,
  });
  const sqliteRepo = new SqliteCartRepository(sqlitePath);
  const cartRepository = new TieredCartRepository(l1Cache, sqliteRepo);

  const catalogInventory = new InMemoryCatalogInventory();
  const pricingEngine = new PricingEngine(DEFAULT_COUPONS);
  const eventBus = new InMemoryEventBus();
  const idempotencyStore = new InMemoryIdempotencyStore();

  const cartService = new CartService({
    cartRepository,
    catalogInventory,
    pricingEngine,
    eventBus,
    idempotencyStore,
  });

  const handler = createHttpHandler({
    cartService,
    catalogInventory,
    eventBus,
  });

  const server = createServer(handler);

  const purgeIntervalMs = config.purgeIntervalMs ?? 5 * 60 * 1000;
  const purgeTimer = setInterval(() => {
    void cartRepository.purgeExpired().catch((err) => {
      console.error('[PurgeWorker Error]', err);
    });
  }, purgeIntervalMs);
  purgeTimer.unref();

  return {
    server,
    cartService,
    catalogInventory,
    pricingEngine,
    eventBus,
    l1Cache,
    sqliteRepo,
    cartRepository,
    async close(): Promise<void> {
      clearInterval(purgeTimer);
      await new Promise<void>((resolve, reject) => {
        if (!server.listening) {
          resolve();
          return;
        }
        server.close((err) => (err ? reject(err) : resolve()));
      });
      sqliteRepo.close();
    },
  };
}

const isMainModule =
  process.argv[1] !== undefined &&
  import.meta.url === pathToFileURL(process.argv[1]).href;

if (isMainModule) {
  const port = Number(process.env.PORT ?? 3000);
  const host = process.env.HOST ?? '0.0.0.0';
  const app = createShoppingCartApp();

  app.server.listen(port, host, () => {
    console.log(
      `[ShoppingCart] Servidor activo en http://${host === '0.0.0.0' ? 'localhost' : host}:${port}`,
    );
  });

  const shutdown = async (signal: string) => {
    console.log(`\n[ShoppingCart] Señal ${signal} recibida. Cerrando conexiones de forma limpia...`);
    await app.close();
    process.exit(0);
  };

  process.on('SIGINT', () => void shutdown('SIGINT'));
  process.on('SIGTERM', () => void shutdown('SIGTERM'));
}

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { Cart } from '../src/domain/cart.ts';
import { DomainError } from '../src/domain/errors.ts';
import { Money } from '../src/domain/money.ts';
import { PricingEngine } from '../src/domain/pricing.ts';
import { DEFAULT_COUPONS } from '../src/infrastructure/catalog/in-memory-catalog-inventory.ts';

describe('Dominio: Money & PricingEngine', () => {
  it('opera en unidades menores exactas sin errores de coma flotante y bloquea mezcla de divisas', () => {
    // En IEEE 754 clásico: 0.1 + 0.2 = 0.30000000000000004
    const a = Money.ofMinor(10, 'EUR');
    const b = Money.ofMinor(20, 'EUR');
    const sum = a.add(b);

    assert.equal(sum.amountMinor, 30);
    assert.equal(sum.format(), '0.30 EUR');

    const usd = Money.ofMinor(100, 'USD');
    assert.throws(
      () => sum.add(usd),
      (err: unknown) => err instanceof DomainError && err.code === 'CURRENCY_MISMATCH',
    );
  });

  it('aplica descuento automático por volumen, cupones con tope, IVA y envío gratuito sobre umbral', () => {
    const engine = new PricingEngine(DEFAULT_COUPONS);
    const cart = Cart.create({ userId: 'usr_1', currency: 'EUR' });

    // 10 unidades x 10.00 EUR = 100.00 EUR (10000 minor)
    // -> Activa dto volumen 5% (500 minor) => base restante 9500 minor
    // -> Cupón BIENVENIDA10 (10% sobre 9500) => 950 minor => base imponible 8550 minor
    // -> Base 85.50 EUR >= 50.00 EUR => envío gratis (0 minor)
    // -> IVA 21% sobre 8550 = round(8550 * 0.21) = 1796 minor
    // -> Total = 8550 + 1796 = 10346 minor (103.46 EUR)
    cart.upsertItem({
      sku: 'USB-CABLE',
      name: 'Cable Trenzado USB-C',
      unitPrice: Money.ofMinor(1000, 'EUR'),
      absoluteQuantity: 10,
    });
    cart.applyCoupon('BIENVENIDA10', engine);

    const view = cart.toView(engine);
    assert.equal(view.pricing.subtotal.amountMinor, 10000);
    assert.equal(view.pricing.discounts.length, 2);
    assert.equal(view.pricing.discountTotal.amountMinor, 1450);
    assert.equal(view.pricing.taxableAmount.amountMinor, 8550);
    assert.equal(view.pricing.shippingAmount.amountMinor, 0);
    assert.equal(view.pricing.taxAmount.amountMinor, 1796);
    assert.equal(view.pricing.grandTotal.amountMinor, 10346);
  });

  it('impide mutaciones sobre carritos expirados o ya finalizados', () => {
    const past = new Date('2025-01-01T00:00:00.000Z');
    const cart = Cart.create({ sessionId: 'sess_expired', now: past });

    const later = new Date('2025-02-01T00:00:00.000Z');
    assert.throws(
      () =>
        cart.upsertItem({
          sku: 'ITEM-1',
          name: 'Test',
          unitPrice: Money.ofMinor(500, 'EUR'),
          quantityDelta: 1,
          now: later,
        }),
      (err: unknown) => err instanceof DomainError && err.code === 'CART_EXPIRED',
    );
  });
});

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import {
  ConcurrencyConflictError,
  DomainError,
  InsufficientStockError,
} from '../src/domain/errors.ts';
import { createShoppingCartApp } from '../src/server.ts';

describe('Aplicación e Infraestructura: Concurrencia, Caché Multinivel, Idempotencia y Saga Checkout', () => {
  it('resuelve escrituras concurrentes sin If-Match mediante reintento optimista y rechaza versiones obsoletas explícitas', async () => {
    const app = createShoppingCartApp({ sqlitePath: ':memory:' });
    try {
      const created = await app.cartService.createOrGetActiveCart({
        userId: 'usr_concurrent',
      });

      // Lanzamos 5 adiciones concurrentes sobre el mismo carrito sin fijar expectedVersion
      await Promise.all([
        app.cartService.addItem({ cartId: created.id, sku: 'USB-HUB-7IN1', quantity: 1 }),
        app.cartService.addItem({ cartId: created.id, sku: 'USB-HUB-7IN1', quantity: 2 }),
        app.cartService.addItem({ cartId: created.id, sku: 'MOUSE-ERGO-WL', quantity: 1 }),
        app.cartService.addItem({ cartId: created.id, sku: 'MECH-KEY-ES', quantity: 1 }),
        app.cartService.addItem({ cartId: created.id, sku: 'USB-HUB-7IN1', quantity: 3 }),
      ]);

      const updated = await app.cartService.getCart(created.id);
      const hubItem = updated.items.find((i) => i.sku === 'USB-HUB-7IN1');
      assert.equal(hubItem?.quantity, 6);
      assert.equal(updated.version, 6);

      // Si un cliente envía explícitamente una versión antigua (expectedVersion: 2), debe fallar con 409
      await assert.rejects(
        () =>
          app.cartService.addItem({
            cartId: created.id,
            sku: 'USB-HUB-7IN1',
            quantity: 1,
            expectedVersion: 2,
          }),
        (err: unknown) => err instanceof ConcurrencyConflictError && err.statusCode === 409,
      );
    } finally {
      await app.close();
    }
  });

  it('invalida la caché L1 automáticamente cuando L2 detecta un cambio externo de otro nodo', async () => {
    const app = createShoppingCartApp({ sqlitePath: ':memory:' });
    try {
      const created = await app.cartService.createOrGetActiveCart({
        sessionId: 'sess_multi_node',
      });
      await app.cartService.addItem({
        cartId: created.id,
        sku: 'MOUSE-ERGO-WL',
        quantity: 1,
      });

      // Simulamos escritura directa en L2 desde otro nodo del clúster (saltando la L1 local)
      const directL2Cart = await app.sqliteRepo.findById(created.id);
      assert.ok(directL2Cart);
      const prevVersion = directL2Cart.version;
      directL2Cart.removeItem('MOUSE-ERGO-WL');
      await app.sqliteRepo.save(directL2Cart, prevVersion);

      // Ahora nuestra instancia intenta guardar con su versión L1 anticuada usando expectedVersion explícito
      await assert.rejects(
        () =>
          app.cartService.addItem({
            cartId: created.id,
            sku: 'MECH-KEY-ES',
            quantity: 1,
            expectedVersion: prevVersion,
          }),
        ConcurrencyConflictError,
      );

      // Tras el conflicto, L1 quedó invalidada y la siguiente lectura refleja el estado real de L2
      const refreshed = await app.cartService.getCart(created.id);
      assert.equal(refreshed.items.length, 0);
      assert.equal(refreshed.version, prevVersion + 1);
    } finally {
      await app.close();
    }
  });

  it('garantiza idempotencia ante reintentos y bloquea reutilización fraudulenta de Idempotency-Key', async () => {
    const app = createShoppingCartApp({ sqlitePath: ':memory:' });
    try {
      const cart = await app.cartService.createOrGetActiveCart({
        userId: 'usr_idem',
      });

      const first = await app.cartService.runIdempotent('key-abc-1', 'fp-1', () =>
        app.cartService.addItem({ cartId: cart.id, sku: 'HEADSET-ANC', quantity: 2 }),
      );
      assert.equal(first.replayed, false);
      assert.equal(first.result.items[0]?.quantity, 2);

      const second = await app.cartService.runIdempotent('key-abc-1', 'fp-1', () =>
        app.cartService.addItem({ cartId: cart.id, sku: 'HEADSET-ANC', quantity: 2 }),
      );
      assert.equal(second.replayed, true);
      // No se duplicó la cantidad a 4
      assert.equal(second.result.items[0]?.quantity, 2);

      // Misma clave pero distinto payload -> 409 IDEMPOTENCY_CONFLICT
      await assert.rejects(
        () =>
          app.cartService.runIdempotent('key-abc-1', 'fp-diferente', () =>
            app.cartService.addItem({ cartId: cart.id, sku: 'HEADSET-ANC', quantity: 5 }),
          ),
        (err: unknown) => err instanceof DomainError && err.code === 'IDEMPOTENCY_CONFLICT',
      );
    } finally {
      await app.close();
    }
  });

  it('ejecuta checkout revalidando cambios de precio, descontando stock y compensando en caso de fallo', async () => {
    const app = createShoppingCartApp({ sqlitePath: ':memory:' });
    try {
      app.catalogInventory.upsertProduct({
        sku: 'LIMITED-GPU',
        name: 'GPU Edición Limitada',
        description: 'Solo 2 unidades',
        unitPriceMinor: 80000,
        currency: 'EUR',
        availableStock: 2,
        active: true,
      });

      const cart = await app.cartService.createOrGetActiveCart({ userId: 'usr_buyer' });
      await app.cartService.addItem({ cartId: cart.id, sku: 'LIMITED-GPU', quantity: 2 });

      // El precio en el catálogo cambia antes del checkout (de 800.00 a 750.00 EUR)
      app.catalogInventory.upsertProduct({
        sku: 'LIMITED-GPU',
        name: 'GPU Edición Limitada',
        description: 'Solo 2 unidades',
        unitPriceMinor: 75000,
        currency: 'EUR',
        availableStock: 2,
        active: true,
      });

      const result = await app.cartService.checkout({
        cartId: cart.id,
        customerEmail: 'comprador@tienda.es',
      });

      assert.equal(result.cart.status, 'CHECKED_OUT');
      assert.equal(result.order.priceAdjustments.length, 1);
      assert.equal(result.order.priceAdjustments[0]?.currentUnitPrice.amountMinor, 75000);
      assert.equal(result.order.pricing.subtotal.amountMinor, 150000);

      // El stock disponible pasó de 2 a 0
      const afterProduct = await app.catalogInventory.getProduct('LIMITED-GPU');
      assert.equal(afterProduct?.availableStock, 0);

      // Un segundo comprador intentando añadir recibe InsufficientStockError
      const otherCart = await app.cartService.createOrGetActiveCart({ userId: 'usr_late' });
      await assert.rejects(
        () =>
          app.cartService.addItem({
            cartId: otherCart.id,
            sku: 'LIMITED-GPU',
            quantity: 1,
          }),
        InsufficientStockError,
      );
    } finally {
      await app.close();
    }
  });
});

import assert from 'node:assert/strict';
import type { AddressInfo } from 'node:net';
import { after, before, describe, it } from 'node:test';
import { createShoppingCartApp, type ShoppingCartApp } from '../src/server.ts';

describe('API HTTP End-to-End', () => {
  let app: ShoppingCartApp;
  let baseUrl: string;

  before(async () => {
    app = createShoppingCartApp({ sqlitePath: ':memory:' });
    await new Promise<void>((resolve) => {
      app.server.listen(0, '127.0.0.1', () => resolve());
    });
    const addr = app.server.address() as AddressInfo;
    baseUrl = `http://127.0.0.1:${addr.port}`;
  });

  after(async () => {
    await app.close();
  });

  it('expone healthcheck, catálogo e interfaz web interactiva', async () => {
    const healthRes = await fetch(`${baseUrl}/health`);
    assert.equal(healthRes.status, 200);
    const health = (await healthRes.json()) as { status: string };
    assert.equal(health.status, 'ok');

    const prodRes = await fetch(`${baseUrl}/api/v1/products`);
    assert.equal(prodRes.status, 200);
    const prodData = (await prodRes.json()) as { products: unknown[] };
    assert.ok(prodData.products.length >= 6);

    const uiRes = await fetch(`${baseUrl}/`);
    assert.equal(uiRes.status, 200);
    assert.match(uiRes.headers.get('content-type') ?? '', /text\/html/);
  });

  it('completa flujo completo: carrito invitado -> ETag/If-Match -> fusión con usuario -> cupón -> checkout', async () => {
    // 1. Crear carrito de invitado y añadir un ratón
    const guestCreate = await fetch(`${baseUrl}/api/v1/carts`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sessionId: 'sess_web_999' }),
    });
    assert.equal(guestCreate.status, 201);
    assert.equal(guestCreate.headers.get('etag'), 'W/"v1"');
    const guestCartId = ((await guestCreate.json()) as { cart: { id: string } }).cart.id;

    const addGuestItem = await fetch(`${baseUrl}/api/v1/carts/${guestCartId}/items`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'If-Match': 'W/"v1"',
        'Idempotency-Key': 'idem-guest-add-1',
      },
      body: JSON.stringify({ sku: 'MOUSE-ERGO-WL', quantity: 2 }),
    });
    assert.equal(addGuestItem.status, 200);
    assert.equal(addGuestItem.headers.get('etag'), 'W/"v2"');

    // Verificar rechazo de ETag obsoleto (409 Conflict)
    const staleAttempt = await fetch(`${baseUrl}/api/v1/carts/${guestCartId}/items`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'If-Match': 'W/"v1"',
      },
      body: JSON.stringify({ sku: 'MECH-KEY-ES', quantity: 1 }),
    });
    assert.equal(staleAttempt.status, 409);

    // 2. El usuario ya tenía un carrito previo con 1 ratón y 1 teclado
    const userCreate = await fetch(`${baseUrl}/api/v1/carts`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ userId: 'usr_maria' }),
    });
    const userCartId = ((await userCreate.json()) as { cart: { id: string } }).cart.id;

    await fetch(`${baseUrl}/api/v1/carts/${userCartId}/items`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sku: 'MOUSE-ERGO-WL', quantity: 1 }),
    });
    await fetch(`${baseUrl}/api/v1/carts/${userCartId}/items`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sku: 'MECH-KEY-ES', quantity: 1 }),
    });

    // 3. El usuario inicia sesión -> fusionamos carrito invitado dentro de usr_maria
    const mergeRes = await fetch(`${baseUrl}/api/v1/carts/merge`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Idempotency-Key': 'idem-merge-maria',
      },
      body: JSON.stringify({ guestCartId, userId: 'usr_maria' }),
    });
    assert.equal(mergeRes.status, 200);
    const mergedBody = (await mergeRes.json()) as {
      cart: { id: string; items: Array<{ sku: string; quantity: number }> };
    };
    assert.equal(mergedBody.cart.id, userCartId);
    const mergedMouse = mergedBody.cart.items.find((i) => i.sku === 'MOUSE-ERGO-WL');
    assert.equal(mergedMouse?.quantity, 3); // 1 del usuario + 2 del invitado

    // 4. Aplicar cupón AHORRA25
    const couponRes = await fetch(`${baseUrl}/api/v1/carts/${userCartId}/coupons`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ code: 'AHORRA25' }),
    });
    assert.equal(couponRes.status, 200);
    const couponBody = (await couponRes.json()) as {
      cart: { couponCode: string; pricing: { discountTotal: { amountMinor: number } } };
    };
    assert.equal(couponBody.cart.couponCode, 'AHORRA25');
    assert.equal(couponBody.cart.pricing.discountTotal.amountMinor, 2500);

    // 5. Checkout idempotente
    const checkoutRes = await fetch(`${baseUrl}/api/v1/carts/${userCartId}/checkout`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Idempotency-Key': 'idem-checkout-maria',
      },
      body: JSON.stringify({
        customerEmail: 'maria@ejemplo.com',
        shippingAddress: 'Calle Alcalá 100, Madrid',
      }),
    });
    assert.equal(checkoutRes.status, 200);
    const checkoutData = (await checkoutRes.json()) as {
      order: { orderId: string };
      cart: { status: string };
    };
    assert.match(checkoutData.order.orderId, /^ord_/);
    assert.equal(checkoutData.cart.status, 'CHECKED_OUT');

    // Reintentar el mismo checkout con la misma Idempotency-Key devuelve exactamente la misma orden
    const replayCheckout = await fetch(`${baseUrl}/api/v1/carts/${userCartId}/checkout`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Idempotency-Key': 'idem-checkout-maria',
      },
      body: JSON.stringify({
        customerEmail: 'maria@ejemplo.com',
        shippingAddress: 'Calle Alcalá 100, Madrid',
      }),
    });
    assert.equal(replayCheckout.status, 200);
    assert.equal(replayCheckout.headers.get('x-idempotent-replay'), 'true');
    const replayData = (await replayCheckout.json()) as { order: { orderId: string } };
    assert.equal(replayData.order.orderId, checkoutData.order.orderId);

    // 6. Verificar publicación de eventos de dominio
    const eventsRes = await fetch(`${baseUrl}/api/v1/events`);
    const eventsData = (await eventsRes.json()) as { events: Array<{ type: string }> };
    assert.ok(eventsData.events.some((e) => e.type === 'cart.checked_out'));
  });
});

